window.__EBT=window.__EBT||{};window.__EBT["ro"]=window.__EBT["ro"]||{};window.__EBT["ro"]["Ps"]=[[1,[[1,"Ferice de omul care nu umblă după sfatul celor răi,"],[2,"dar plăcerea lui este în Legea Domnului."],[3,"El va fi ca un copac plantat lângă pâraiele de apă,"],[4,"Cei răi nu sunt așa,"],[5,"De aceea cei răi nu vor rezista la judecată,"],[6,"Căci Domnul cunoaște calea celor drepți,"]]],[2,[[1,"De ce se înfurie națiunile,"],[2,"Regii pământului iau atitudine,"],[3,"„Să le rupem legăturile,"],[4,"Cel ce stă în ceruri va râde."],[5,"Atunci le va vorbi în mânia lui,"],[6,"„Totuși l-am așezat pe Împăratul meu pe dealul meu sfânt al Sionului.”"],[7,"Voi spune despre decret:"],[8,"Cereți de la mine și voi da neamurilor ca moștenire,"],[9,"Le vei sparge cu un toiag de fier."],[10,"Acum, deci, fiți înțelepți, împăraților."],[11,"Slujiți Domnului cu frică,"],[12,"Omagi sincer Fiului, ca nu cumva să se mânie și să pieriți pe drum,"]]],[3,[[1,"Doamne, cât s-au înmulțit potrivnicii mei!"],[2,"Mulți sunt cei care spun despre sufletul meu:"],[3,"Dar Tu, Doamne, ești un scut în jurul meu,"],[4,"strig către Domnul cu glasul meu,"],[5,"M-am culcat și am dormit."],[6,"Nu mă voi teme de zeci de mii de oameni"],[7,"Scoală-te, Doamne!"],[8,"Mântuirea îi aparține lui Iahve."]]],[4,[[1,"Răspunde-mi când chem, Dumnezeul dreptății mele."],[2,"Fiii oamenilor, până când slava mea se va preface în dezonoare?"],[3,"Dar să știți că Domnul și-a pus deoparte pe cel evlavios;"],[4,"Rămâi cu uimire și nu păcătui."],[5,"Oferiți jertfele dreptății."],[6,"Mulți spun: „Cine ne va arăta vreun bine?”"],[7,"Tu ai pus bucurie în inima mea,"],[8,"În pace mă voi culca și voi dormi,"]]],[5,[[1,"Ascultă cuvintele mele, Doamne!"],[2,"Ascultă glasul strigătului meu, Regele meu și Dumnezeul meu,"],[3,"Doamne, dimineața vei auzi glasul meu."],[4,"Căci nu ești un Dumnezeu căruia îi place răutatea."],[5,"Aroganții nu vor sta în ochii tai."],[6,"Îi vei nimici pe cei care vorbesc minciuni."],[7,"Dar în ceea ce mă privește, în abundența bunătății tale iubitoare voi intra în casa ta."],[8,"Condu-mă, Doamne, în dreptatea Ta, din cauza vrăjmașilor mei."],[9,"Căci nu este credincioşie în gura lor."],[10,"Ține-i vinovați, Doamne."],[11,"Dar să se bucure toți cei care se adăpostesc în tine."],[12,"Căci vei binecuvânta pe cei drepți."]]],[6,[[1,"Doamne, nu mă certa în mânia Ta,"],[2,"Miluiește-mă, Doamne, că sunt slăbit."],[3,"Sufletul meu este și el într-o mare suferință."],[4,"Întoarce-te, Iahve. Eliberează-mi sufletul,"],[5,"Căci în moarte nu există amintire despre tine."],[6,"Sunt obosit de geamătul meu."],[7,"Ochiul meu se irosește din cauza durerii."],[8,"Depărtați-vă de la mine, toți lucrătorii fărădelegii,"],[9,"Domnul mi-a ascultat cererea."],[10,"Fie ca toți vrăjmașii mei să fie rușinați și îngroziți."]]],[7,[[1,"Doamne, Dumnezeul meu, mă adăpostesc în Tine."],[2,"ca nu cumva să-mi sfâșie sufletul ca un leu,"],[3,"DOAMNE, Dumnezeul meu, dacă am făcut aceasta,"],[4,"dacă i-am răsplătit răul celui care era împăcat cu mine"],[5,"vrăjmașul să-mi urmărească sufletul și să-l ajungă;"],[6,"Scoală-te, Doamne, în mânia Ta."],[7,"Lăsați adunarea popoarelor să vă înconjoare."],[8,"Domnul dă judecata popoarelor."],[9,"O, să se termine răutatea celor răi,"],[10,"Scutul meu este cu Dumnezeu,"],[11,"Dumnezeu este un judecător drept,"],[12,"Dacă un om nu se pocăiește, își va ascuți sabia;"],[13,"Și-a pregătit și instrumentele morții."],[14,"Iată, el suferă de nelegiuire."],[15,"A săpat o groapă,"],[16,"Necazurile pe care le provoacă se vor întoarce în capul lui."],[17,"Voi mulțumi Domnului după dreptatea Lui,"]]],[8,[[1,"Doamne, Domnul nostru, cât de mare este numele Tău pe tot pământul!"],[2,"Din buzele pruncilor și pruncilor ai întărit putere,"],[3,"Când mă gândesc la cerurile tale, lucrarea degetelor tale,"],[4,"ce este omul, ca te gandesti la el?"],[5,"Căci l-ai făcut puțin mai jos decât îngerii,"],[6,"Îl faci stăpânitor peste lucrările mâinilor tale."],[7,"Toate oile și bovinele,"],[8,"păsările cerului, peștii mării,"],[9,"Domnul, Domnul nostru,"]]],[9,[[1,"Îi voi mulțumi Domnului din toată inima."],[2,"Mă voi bucura și mă voi bucura de tine."],[3,"Când dușmanii mei se întorc,"],[4,"Căci mi-ați susținut cauza dreaptă."],[5,"ai mustrat neamurile."],[6,"Inamicul este depășit de o ruină nesfârșită."],[7,"Dar Domnul domnește pentru totdeauna."],[8,"El va judeca lumea în dreptate."],[9,"Domnul va fi şi un turn înalt pentru cei asupriţi;"],[10,"Cei care-ți cunosc numele își vor pune încrederea în tine,"],[11,"Cântați laude Domnului, care locuiește în Sion,"],[12,"Căci cel ce răzbună sângele își amintește de ele."],[13,"Miluiește-mă, Doamne."],[14,"ca să arăt toată lauda ta."],[15,"Neamurile s-au scufundat în groapa pe care au făcut-o."],[16,"Domnul s-a făcut cunoscut."],[17,"Cei răi se vor întoarce în mormânt,"],[18,"Căci cei nevoiași nu vor fi mereu uitați,"],[19,"Scoală-te, Doamne! Nu lăsa omul să prevaleze."],[20,"Pune-i frică, Doamne!"]]],[10,[[1,"De ce stai departe, Doamne?"],[2,"În aroganță, cei răi îi vânează pe cei slabi."],[3,"Căci cei răi se laudă cu poftele inimii lui."],[4,"Cel rău, în mândria feței sale,"],[5,"Căile Lui sunt prospere în orice moment."],[6,"El spune în inima lui: „Nu voi fi zguduit."],[7,"Gura lui este plină de blestem, înșelăciune și asuprire."],[8,"El stă la pândă lângă sate."],[9,"El pândește în secret ca un leu în ambuscadă."],[10,"Cei neputincioși sunt zdrobiți."],[11,"El spune în inima lui: „Dumnezeu a uitat."],[12,"Scoală-te, Doamne!"],[13,"De ce îl condamnă cel rău pe Dumnezeu,"],[14,"Dar tu vezi necazuri și durere."],[15,"Rupe brațul celor răi."],[16,"Domnul este Împărat în vecii vecilor!"],[17,"Doamne, ai auzit dorința celor smeriți."],[18,"să judece pe orfan și pe cel asuprit,"]]],[11,[[1,"În Domnul, mă adăpostesc."],[2,"Căci, iată, cei răi își îndoaie arcurile."],[3,"Dacă fundațiile sunt distruse,"],[4,"Domnul este în templul Său sfânt."],[5,"Domnul cercetează pe cei drepți,"],[6,"Pe cei răi va ploua cărbuni aprinși;"],[7,"Căci Domnul este drept."]]],[12,[[1,"Ajută, Doamne; căci omul evlavios încetează."],[2,"Fiecare își minte aproapele."],[3,"Domnul să taie toate buzele măgulitoare,"],[4,"care au spus: „Cu limba noastră vom birui."],[5,"„Din pricina asupririi celor slabi și din cauza gemetelor celor nevoiași,"],[6,"Cuvintele Domnului sunt cuvinte fără cusur,"],[7,"Le vei păzi, Doamne."],[8,"Cei răi umblă din toate părțile,"]]],[13,[[1,"Cât timp, Doamne?"],[2,"Până când voi lua sfat în sufletul meu,"],[3,"Iată și răspunde-mi, Doamne, Dumnezeul meu."],[4,"ca nu cumva dușmanul meu să zică: „L-am biruit”;"],[5,"Dar am încredere în bunătatea ta iubitoare."],[6,"voi cânta Domnului,"]]],[14,[[1,"Nebunul a spus în inima lui: „Nu există Dumnezeu”."],[2,"Domnul a privit din ceruri spre copiii oamenilor,"],[3,"Toate au plecat deoparte."],[4,"Toți lucrătorii fărădelegii să nu aibă cunoștință,"],[5,"Acolo erau în mare frică,"],[6,"Începi planul săracilor,"],[7,"O, dacă ar veni mântuirea lui Israel din Sion!"]]],[15,[[1,"Doamne, cine va locui în sanctuarul Tău?"],[2,"Cel ce umblă fără prihană și face ce este drept,"],[3,"cel care nu defăimește cu limba,"],[4,"în ochii căruia un om ticălos este disprețuit,"],[5,"cel care nu-și împrumută banii pentru cămătărie,"]]],[16,[[1,"Păzește-mă, Doamne, că mă adăpostesc în Tine."],[2,"Suflete al meu, ai spus Domnului: „Tu ești Domnul meu."],[3,"Cât despre sfinții care sunt pe pământ,"],[4,"Se vor înmulți întristarile lor cei care dau daruri altui dumnezeu."],[5,"Domnul mi-a dat porția și paharul."],[6,"Mi-au căzut rândurile în locuri plăcute."],[7,"Voi binecuvânta pe Domnul, care mi-a dat sfat."],[8,"Întotdeauna l-am pus pe Domnul înaintea mea."],[9,"De aceea inima mea se bucură și limba mea se bucură."],[10,"Căci nu-mi vei lăsa sufletul în mormânt,"],[11,"Îmi vei arăta calea vieții."]]],[17,[[1,"Ascultă, Doamne, cererea mea dreaptă."],[2,"Lasă sentința mea să iasă din prezența ta."],[3,"Mi-ai dovedit inima."],[4,"Cât despre faptele oamenilor, prin cuvântul buzelor tale,"],[5,"Pașii mei s-au ținut tari de cărările tale."],[6,"Te-am chemat, căci îmi vei răspunde, Doamne."],[7,"Arată-ți minunata bunătate iubitoare,"],[8,"Păstrează-mă ca pe pruncul ochilor tăi."],[9,"de la cei răi care mă asupresc,"],[10,"Își închid inimile insensibile."],[11,"Acum ne-au înconjurat în pașii noștri."],[12,"El este ca un leu care este lacom de prada lui,"],[13,"Scoală-te, Doamne, înfruntă-l."],[14,"de la oameni de mâna Ta, Doamne,"],[15,"Cât despre mine, îți voi vedea fața în dreptate."]]],[18,[[1,"Te iubesc, Doamne, puterea mea."],[2,"Domnul este stânca mea, fortăreața mea și izbăvitorul meu;"],[3,"Chem pe Domnul, care este vrednic de lăudat;"],[4,"Corzile morții m-au înconjurat."],[5,"Corzile mormântului erau în jurul meu."],[6,"În necazul meu am chemat pe Domnul,"],[7,"Apoi pământul s-a cutremurat și a tremurat."],[8,"Fum ieşea din nări."],[9,"El a plecat și cerurile și a coborât."],[10,"A călărit pe un heruvim și a zburat."],[11,"El a făcut din întuneric ascunzătoarea lui, pavilionul său în jurul lui,"],[12,"La strălucirea dinaintea lui au trecut norii lui groși,"],[13,"Şi Domnul a tunat pe cer."],[14,"El și-a trimis săgețile și le-a împrăștiat."],[15,"Apoi au apărut canalele apelor."],[16,"El a trimis de sus."],[17,"El m-a izbăvit de dușmanul meu puternic,"],[18,"Au venit asupra mea în ziua nenorocirii mele,"],[19,"M-a scos și pe mine într-un loc mare."],[20,"Domnul mi-a răsplătit după dreptatea mea."],[21,"Căci am păzit căile Domnului,"],[22,"Căci toate rânduielile lui erau înaintea mea."],[23,"Am fost și eu fără vină cu el."],[24,"De aceea, Domnul mi-a răsplătit după dreptatea mea,"],[25,"Cu cei milostivi te vei arăta milostiv."],[26,"Cu cei puri, te vei arăta pur."],[27,"Căci vei mântui poporul îndurerat,"],[28,"Căci Tu vei aprinde lampa mea, Doamne."],[29,"Căci prin tine, înaintez printr-o trupă."],[30,"Cât despre Dumnezeu, calea lui este perfectă."],[31,"Căci cine este Dumnezeu, în afară de Domnul?"],[32,"Dumnezeul care mă înarmează cu putere și îmi face calea desăvârșită?"],[33,"El îmi face picioarele ca niște picioare de căprioară,"],[34,"El îmi învață mâinile la război,"],[35,"Mi-ai dat și scutul mântuirii tale."],[36,"Mi-ai mărit pașii sub mine,"],[37,"Îmi voi urmări pe vrăjmașii mei și-i voi atinge."],[38,"Îi voi lovi, ca să nu se poată ridica."],[39,"Căci m-ai înarmat cu putere pentru luptă."],[40,"Ai făcut și pe vrăjmașii mei să-mi întoarcă spatele,"],[41,"Au strigat, dar nu era pe cine să mântuiască;"],[42,"Apoi le-am bătut mărunt ca praful dinaintea vântului."],[43,"M-ai izbăvit de eforturile poporului."],[44,"De îndată ce vor auzi de mine, mă vor asculta."],[45,"Străinii vor dispărea,"],[46,"Yahweh trăiește! Binecuvântată să fie stânca mea."],[47,"chiar și Dumnezeul care se răzbună pentru mine,"],[48,"El mă scapă de dușmanii mei."],[49,"De aceea Îți voi mulțumi, Doamne, printre neamuri,"],[50,"El dă mare izbăvire regelui său,"]]],[19,[[1,"Cerurile declară slava lui Dumnezeu."],[2,"Zi de zi ei vorbesc,"],[3,"Nu există vorbire și nici limbaj"],[4,"Glasul lor s-a auzit prin tot pământul,"],[5,"care este ca un mire care iese din camera lui,"],[6,"Ieșirea Lui este de la capătul cerurilor,"],[7,"Legea Domnului este desăvârșită, restaurând sufletul."],[8,"Preceptele Domnului sunt drepte, bucurând inima."],[9,"Frica de Domnul este curată, dăinuind în veci."],[10,"Sunt mai de dorit decât aurul, da, decât mult aur fin,"],[11,"În plus, servitorul tău este avertizat de ei."],[12,"Cine îi poate discerne greșelile?"],[13,"Ferește-ți și pe slujitorul tău de păcatele înfățișate."],[14,"Lasă cuvintele gurii mele și meditația inimii mele"]]],[20,[[1,"Domnul să vă răspundă în ziua necazului."],[2,"să-ți trimită ajutor de la sanctuar,"],[3,"amintește-ți toate ofertele tale,"],[4,"Fie ca el să-ți îndeplinească dorința inimii tale,"],[5,"Vom triumfa în mântuirea ta."],[6,"Acum știu că Domnul îl mântuiește pe unsul său."],[7,"Unii se încred în care, iar alții în cai,"],[8,"Sunt plecați și căzuți,"],[9,"Salvează, Doamne!"]]],[21,[[1,"Împăratul se bucură de puterea ta, Doamne!"],[2,"I-ai dat dorința inimii lui,"],[3,"Căci îl întâlnești cu binecuvântările bunătății."],[4,"Ți-a cerut viață și tu i-ai dat-o,"],[5,"Slava Lui este mare în mântuirea ta."],[6,"Căci îl faci cel mai binecuvântat pentru totdeauna."],[7,"Căci împăratul se încrede în Domnul."],[8,"Mâna ta va descoperi toți inamicii tăi."],[9,"Le vei face ca un cuptor de foc în timpul mâniei tale."],[10,"Vei nimici descendenții lor de pe pământ,"],[11,"Căci au intenționat răul împotriva ta."],[12,"Căci îi vei face să se întoarcă cu spatele,"],[13,"Înălță-te, Doamne, în puterea ta,"]]],[22,[[1,"Dumnezeul meu, Dumnezeul meu, de ce m-ai părăsit?"],[2,"Doamne, plâng ziua, dar tu nu răspunzi;"],[3,"Dar tu ești sfânt,"],[4,"Părinții noștri au avut încredere în tine."],[5,"Au strigat către tine și au fost izbăviți."],[6,"Dar eu sunt un vierme și niciun om;"],[7,"Toți cei care mă văd își bat joc de mine."],[8,"„Se încrede în Domnul."],[9,"Dar m-ai scos din pântece."],[10,"Am fost aruncat peste tine din pântecele mamei mele."],[11,"Nu fi departe de mine, căci necazurile sunt aproape."],[12,"M-au înconjurat mulți tauri."],[13,"Ei deschid gura larg împotriva mea,"],[14,"Sunt turnat ca apa."],[15,"Puterea mea este uscată ca un ciob de oală."],[16,"Căci câinii m-au înconjurat."],[17,"Îmi pot număra toate oasele."],[18,"Îmi împart hainele între ele."],[19,"Dar nu fi departe, Doamne."],[20,"Eliberează-mi sufletul de sabie,"],[21,"Salvează-mă din gura leului!"],[22,"Voi vesti numele tău fraților mei."],[23,"Voi cei ce vă temeți de Domnul, lăudați-L!"],[24,"Căci el nu a disprețuit și nici nu a urâit necazul celor necăjiți,"],[25,"Lauda mea pentru tine vine în marea adunare."],[26,"Cei smeriți vor mânca și se vor sătura."],[27,"Toate marginile pământului se vor aduce aminte și se vor întoarce la Domnul."],[28,"Căci împărăția este a Domnului."],[29,"Toți bogații pământului vor mânca și se vor închina."],[30,"Posteritatea îl va sluji."],[31,"Ei vor veni și vor vesti dreptatea Lui unui popor care se va naște,"]]],[23,[[1,"Domnul este păstorul meu;"],[2,"Mă face să mă culc pe pășuni verzi."],[3,"El îmi restabilește sufletul."],[4,"Chiar dacă merg prin valea umbrei morții,"],[5,"Pregătiți o masă înaintea mea"],[6,"Cu siguranță bunătatea și bunătatea iubitoare mă vor urma în toate zilele vieții mele,"]]],[24,[[1,"Pământul este al Domnului, cu plinătatea lui;"],[2,"Căci a întemeiat-o pe mări,"],[3,"Cine poate urca pe dealul Domnului?"],[4,"Cel care are mâinile curate și inima curată;"],[5,"El va primi o binecuvântare de la Domnul,"],[6,"Aceasta este generația celor care-L caută,"],[7,"Ridicați capetele, porți!"],[8,"Cine este Regele gloriei?"],[9,"Ridicați-vă capetele, porți;"],[10,"Cine este acest Împărat al gloriei?"]]],[25,[[1,"Spre Tine, Doamne, îmi înalț sufletul."],[2,"Doamne, m-am încrezut în tine."],[3,"Da, nimeni care te așteaptă nu va fi rușinat."],[4,"Arată-mi căile Tale, Doamne."],[5,"Călăuzește-mă în adevărul Tău și învață-mă,"],[6,"Doamne, adu-ți aminte de îndurările Tale și de bunătatea Ta iubitoare,"],[7,"Nu-ți aduce aminte de păcatele tinereții mele și nici de păcatele mele."],[8,"Bun și drept este Domnul,"],[9,"El îi va călăuzi pe cei smeriți în dreptate."],[10,"Toate căile Domnului sunt bunătate iubitoare și adevăr"],[11,"Pentru numele Tău, Doamne,"],[12,"Ce om este cel care se teme de Domnul?"],[13,"Sufletul lui va locui în largul lui."],[14,"Prietenia Domnului este cu cei ce se tem de El."],[15,"Ochii mei sunt mereu pe Domnul,"],[16,"Întoarce-te la mine și ai milă de mine,"],[17,"Necazurile inimii mele sunt mari."],[18,"Uită-te la necazul meu și necazul meu."],[19,"Luați în considerare dușmanii mei, căci sunt mulți."],[20,"O, păzește-mi sufletul și izbăvește-mă."],[21,"Să mă păstreze integritatea și dreptatea,"],[22,"Doamne, mântuiește pe Israel"]]],[26,[[1,"Judecă-mă, Doamne, căci am umblat în neprihănirea mea."],[2,"Cercetează-mă, Doamne, și dovedește-mă."],[3,"Căci bunătatea ta iubitoare este înaintea ochilor mei."],[4,"Nu m-am așezat cu oameni înșelători,"],[5,"Urăsc adunarea răufăcătorilor,"],[6,"Îmi voi spăla mâinile în nevinovăție,"],[7,"ca să fac să se audă glasul mulțumirii"],[8,"Doamne, iubesc locuința casei tale,"],[9,"Nu-mi aduna sufletul cu păcătoșii,"],[10,"în mâinile cărora este răutatea;"],[11,"Dar în ceea ce mă privește, voi merge în integritatea mea."],[12,"Piciorul meu stă într-un loc uniform."]]],[27,[[1,"Domnul este lumina mea și mântuirea mea."],[2,"Când au venit la mine răufăcătorii să-mi mănânce carnea,"],[3,"Deși o armată ar tăbăra împotriva mea,"],[4,"Un lucru l-am cerut Domnului, pe care îl voi căuta:"],[5,"Căci în ziua necazului, el mă va ține pe ascuns în pavilionul său."],[6,"Acum capul meu va fi ridicat deasupra dușmanilor mei din jurul meu."],[7,"Ascultă, Doamne, când strig cu glasul meu."],[8,"Când ai spus: „Căutați fața mea”,"],[9,"Nu-ți ascunde fața de mine."],[10,"Când tatăl meu și mama mă părăsesc,"],[11,"Învață-mă calea Ta, Doamne."],[12,"Nu mă lăsa sub dorința adversarilor mei,"],[13,"Inca sunt increzator in asta:"],[14,"Așteaptă-l pe Iahve."]]],[28,[[1,"La Tine, Doamne, chem."],[2,"Ascultă glasul cererilor mele, când strig către tine,"],[3,"Nu mă trage departe cu cei răi,"],[4,"Dă-le după lucrarea lor și după răutatea faptelor lor."],[5,"Pentru că nu respectă lucrările Domnului,"],[6,"Binecuvântat să fie Domnul,"],[7,"Domnul este puterea mea și scutul meu."],[8,"Domnul este puterea lor."],[9,"Salvează-ți oamenii,"]]],[29,[[1,"Dați Domnului, fiilor celor puternici,"],[2,"Dați Domnului slava cuvenită Numelui Său."],[3,"Glasul Domnului este pe ape."],[4,"Vocea lui Yahweh este puternică."],[5,"Glasul Domnului sparge cedrii."],[6,"El îi face să sară și pe ei ca un vițel;"],[7,"Glasul lui Yahwe lovește cu fulgere."],[8,"Glasul Domnului zguduie pustia."],[9,"Glasul Domnului face căpriorul să nască,"],[10,"Domnul a stat pe tron ​​la Potop."],[11,"Domnul va da putere poporului Său."]]],[30,[[1,"Te voi lăuda, Doamne, căci m-ai înviat,"],[2,"Doamne, Dumnezeul meu, am strigat către Tine,"],[3,"Doamne, Tu mi-ai scos sufletul din mormânt."],[4,"Cântați laudă Domnului, sfinților Săi."],[5,"Căci furia lui este doar pentru o clipă."],[6,"Cât despre mine, am spus în prosperitatea mea:"],[7,"Tu, Doamne, când m-ai făcut bine, ai întărit muntele meu;"],[8,"Am strigat către Tine, Doamne."],[9,"„Ce folos să fie nimicirea mea, dacă mă cobor în groapă?"],[10,"Ascultă, Doamne, și ai milă de mine."],[11,"Mi-ai transformat doliu în dans pentru mine."],[12,"ca să-ți laude inima mea și să nu tacă."]]],[31,[[1,"În Tine, Doamne, mă adăpostesc."],[2,"Pleacă-ți urechea înaintea mea."],[3,"Căci tu ești stânca mea și fortăreața mea,"],[4,"Scoate-mă din plasa pe care mi l-au întins pe ascuns,"],[5,"În mâna ta îmi încredințez spiritul."],[6,"Urăsc pe cei care privesc deșertăciunile mincinoase,"],[7,"Mă voi bucura și mă voi bucura de bunătatea ta iubitoare,"],[8,"Nu m-ai închis în mâna dușmanului."],[9,"Miluiește-mă, Doamne, că sunt în necaz."],[10,"Căci viața mea este petrecută cu tristețe,"],[11,"Din cauza tuturor adversarilor mei am devenit cu totul disprețuitor față de vecinii mei,"],[12,"Sunt uitat din inimile lor ca un mort."],[13,"Căci am auzit defăimarea multora, groaza de pretutindeni,"],[14,"Dar eu mă încred în Tine, Doamne."],[15,"Vremurile mele sunt în mâna ta."],[16,"Fă-ți fața să strălucească pe slujitorul tău."],[17,"Să nu fiu dezamăgit, Doamne, căci Te-am chemat."],[18,"Lasă buzele mincinoase să fie mute,"],[19,"O, cât de mare este bunătatea ta,"],[20,"La adăpostul prezenței tale îi vei ascunde de uneltirile omului."],[21,"Lăudat să fie Domnul,"],[22,"În ceea ce mă privește, am spus în graba mea: „Sunt rupt dinaintea ochilor tăi”."],[23,"O, iubiți-vă pe Domnul, voi toți sfinții Lui!"],[24,"Fii puternic și lasă-ți inima să ia curaj,"]]],[32,[[1,"Ferice de cel a cărui neascultare este iertată,"],[2,"Binecuvântat este omul căruia Domnul nu-l pune pe seama nelegiuirii,"],[3,"Când am tăcut, oasele mi s-au irosit prin gemetele mele toată ziua."],[4,"Căci zi și noapte mâna ta era grea asupra mea."],[5,"Ți-am recunoscut păcatul meu."],[6,"Pentru aceasta, oricine este evlavios să se roage la tine într-un timp când vei putea fi găsit."],[7,"Tu ești ascunzătoarea mea."],[8,"Te voi instrui și te voi învăța calea pe care vei merge."],[9,"Nu fi ca calul, sau ca catârul, care nu au pricepere,"],[10,"Multe dureri vin la cei răi,"],[11,"Bucurați-vă în Domnul și bucurați-vă, drepți!"]]],[33,[[1,"Bucurați-vă în Domnul, drepți!"],[2,"Mulțumiți Domnului cu lira."],[3,"Cântă-i o melodie nouă."],[4,"Căci cuvântul Domnului este drept."],[5,"El iubește dreptatea și dreptatea."],[6,"Prin cuvântul Domnului, cerurile au fost făcute:"],[7,"El adună apele mării ca o grămadă."],[8,"Să se teamă de Domnul tot pământul."],[9,"Căci el a vorbit și s-a făcut."],[10,"Domnul face nimic sfatul neamurilor."],[11,"Sfatul Domnului rămâne în veac,"],[12,"Binecuvântat este neamul al cărui Dumnezeu este Domnul,"],[13,"Domnul priveste din cer."],[14,"Din locul în care locuiește, el privește pe toți locuitorii pământului,"],[15,"el care modelează toate inimile lor;"],[16,"Nu există niciun rege salvat de mulțimea unei armate."],[17,"Un cal este un lucru zadarnic pentru siguranță,"],[18,"Iată, ochii Domnului este asupra celor ce se tem de El,"],[19,"să-și izbăvească sufletul de la moarte,"],[20,"Sufletul nostru a așteptat pe Domnul."],[21,"Căci inima noastră se bucură de El,"],[22,"Bunătatea Ta iubitoare să fie asupra noastră, Doamne,"]]],[34,[[1,"Voi binecuvânta pe Domnul tot timpul."],[2,"Sufletul meu se va lăuda în Domnul."],[3,"O, mărește-l pe Domnul cu mine."],[4,"L-am căutat pe Domnul și el mi-a răspuns:"],[5,"Se uitau la el și erau strălucitori."],[6,"Acest sărman a strigat și Domnul l-a auzit,"],[7,"Îngerul Domnului tăbărește în jurul celor ce se tem de El,"],[8,"O, gustați și vedeți că Domnul este bun."],[9,"Temeți-vă de Domnul, voi sfinții Lui,"],[10,"Tinerii de lei le lipsesc și suferă de foame,"],[11,"Veniți, copii, ascultați-mă."],[12,"Cine este cineva care își dorește viața,"],[13,"Păstrează-ți limba de rău,"],[14,"Pleacă de la rău și fă binele."],[15,"Ochii Domnului sunt către cei drepți."],[16,"Fața Domnului este împotriva celor ce fac răul,"],[17,"Cei neprihăniți strigă și Domnul aude,"],[18,"Domnul este aproape de cei care au inima zdrobită,"],[19,"Multe sunt necazurile celor neprihăniți,"],[20,"Își protejează toate oasele."],[21,"Răul îi va ucide pe cei răi."],[22,"Domnul mântuiește sufletul slujitorilor Săi."]]],[35,[[1,"Cercetă-te, Doamne, cu cei ce se ceartă cu mine."],[2,"Prinde scutul și clatele,"],[3,"Brandează sulița și blochează pe cei care mă urmăresc."],[4,"Fie ca cei care caută sufletul meu să fie dezamăgiți și aduși la dezonoare."],[5,"Să fie ca pleava înaintea vântului,"],[6,"Să le fie drumul întunecat și alunecos,"],[7,"Căci fără motiv și-au ascuns plasa într-o groapă pentru mine."],[8,"Lasă distrugerea să vină asupra lui pe nesimțite."],[9,"Sufletul meu se va bucura în Domnul."],[10,"Toate oasele mele vor zice: „Doamne, care este ca Tine,"],[11,"Se ridică martori nedrepți."],[12,"Ei mă răsplătesc rău pentru bine,"],[13,"Dar în ceea ce mă privește, când erau bolnavi, îmbrăcămintea mea era de sac."],[14,"M-am comportat ca și cum ar fi fost prietenul meu sau fratele meu."],[15,"Dar în necazurile mele, ei s-au bucurat și s-au adunat."],[16,"Asemenea batjocoritorilor profani în sărbători,"],[17,"Doamne, cât timp vei privi?"],[18,"Îți voi mulțumi în marea adunare."],[19,"Nu lăsați cei care sunt dușmanii mei pe nedrept să se bucure de mine;"],[20,"Căci ei nu vorbesc pace,"],[21,"Da, au deschis gura larg împotriva mea."],[22,"Ai văzut-o, Doamne. Nu taceti."],[23,"Trezeşte-te! Ridică-te să mă aperi, Doamne!"],[24,"Dreptate-mă, Doamne, Dumnezeul meu, după dreptatea Ta."],[25,"Nu-i lăsa să spună în inima lor: \"Aha! Așa vrem noi!\""],[26,"Să fie dezamăgiți și încurcați împreună cei care se bucură de nenorocirea mea."],[27,"Să strige de bucurie și să se bucure cei care favorizează cauza mea dreaptă."],[28,"Limba mea va vorbi toată ziua despre dreptatea ta și despre lauda ta."]]],[36,[[1,"O revelație este în inima mea despre neascultarea celor răi:"],[2,"Căci se măgulește în propriii lui ochi,"],[3,"Cuvintele gurii lui sunt nelegiuire și înșelăciune."],[4,"El plănuiește nelegiuirea pe patul său."],[5,"Bunătatea Ta iubitoare, Doamne, este în ceruri."],[6,"Dreptatea ta este ca munții lui Dumnezeu."],[7,"Cât de prețioasă este bunătatea ta iubitoare, Doamne!"],[8,"Ei vor fi mulțumiți din belșug de abundența casei tale."],[9,"Căci cu tine este izvorul vieții."],[10,"O, continuă-ți bunătatea iubitoare față de cei care te cunosc,"],[11,"Nu lăsa piciorul mândriei să vină împotriva mea."],[12,"Acolo au căzut lucrătorii fărădelegii."]]],[37,[[1,"Nu te supăra din cauza răufăcătorilor,"],[2,"Căci în curând vor fi tăiați ca iarba,"],[3,"Încrede-te în Domnul și fă binele."],[4,"De asemenea, bucură-te de Domnul,"],[5,"Încredințează-ți drumul către Domnul."],[6,"El va face ca dreptatea ta să strălucească ca lumina,"],[7,"Odihnește-te în Domnul și așteaptă-L cu răbdare."],[8,"Încetează de la mânie și părăsește mânia."],[9,"Căci răufăcătorii vor fi nimiciți,"],[10,"Pentru încă puţin timp, şi cei răi nu vor mai fi."],[11,"Dar cei smeriți vor moșteni țara,"],[12,"Cei răi complotează împotriva celui drept,"],[13,"Domnul va râde de el,"],[14,"Cei răi au scos sabia și și-au înclinat arcul,"],[15,"Sabia lor va intra în inima lor."],[16,"Mai bine este puțin ce are cel drept,"],[17,"Căci brațele celor răi vor fi zdrobite,"],[18,"Domnul cunoaște zilele celor desăvârșiți."],[19,"Ei nu vor fi dezamăgiți în vremea răului."],[20,"Dar cei răi vor pieri."],[21,"Cei răi se împrumută și nu plătesc înapoi,"],[22,"Căci cei care sunt binecuvântați de el vor moșteni țara."],[23,"Pașii omului sunt așezați de Domnul."],[24,"Deși se poticnește, nu va cădea,"],[25,"Am fost tânăr și acum sunt bătrân,"],[26,"Toată ziua se ocupă cu bunăvoință și împrumută."],[27,"Pleacă de la rău și fă binele."],[28,"Căci Domnul iubește dreptatea,"],[29,"Cei neprihăniți vor moșteni țara,"],[30,"Gura drepților vorbește despre înțelepciune."],[31,"Legea Dumnezeului său este în inima lui."],[32,"Cei răi privesc pe cei drepți,"],[33,"Domnul nu-l va lăsa în mâna lui,"],[34,"Așteaptă pe Domnul și păzește calea Lui,"],[35,"Am văzut pe cei răi cu mare putere,"],[36,"Dar el a trecut și iată că nu era."],[37,"Observați omul desăvârșit și vedeți pe cel drept,"],[38,"Cât despre păcătoși, ei vor fi nimiciți împreună."],[39,"Dar mântuirea celor drepți este de la Domnul."],[40,"Domnul îi ajută și îi salvează."]]],[38,[[1,"Doamne, nu mă certa în mânia Ta,"],[2,"Căci săgețile tale m-au străpuns,"],[3,"Nu este sănătos în trupul meu din cauza indignării tale,"],[4,"Căci fărădelegile mele au trecut peste capul meu."],[5,"Rănile mele sunt urâte și corupte"],[6,"Mă doare și m-am închinat foarte mult."],[7,"Căci talia mea este plină de arsuri."],[8,"Sunt leșin și grav învinețit."],[9,"Doamne, toată dorința mea este înaintea Ta."],[10,"Inima îmi bate."],[11,"Iubiții mei și prietenii mei stau departe de ciuma mea."],[12,"De asemenea, cei care caută viața mea întind capcane."],[13,"Dar eu, ca surd, nu aud."],[14,"Da, sunt ca un om care nu aude,"],[15,"Căci nădăjduiesc în Tine, Doamne."],[16,"Căci am zis: „Nu-i lăsa să se bucure de mine,"],[17,"Căci sunt gata să cad."],[18,"Căci îmi voi vesti nelegiuirea."],[19,"Dar dușmanii mei sunt puternici și mulți."],[20,"Cei care dau rău pentru bine îmi sunt și potrivnici,"],[21,"Nu mă părăsi, Doamne."],[22,"Grăbește-te să mă ajuți,"]]],[39,[[1,"Am spus: „Îmi voi păzi căile mele, ca să nu păcătuiesc cu limba mea."],[2,"Eram mut de tăcere."],[3,"Inima mea era fierbinte în mine."],[4,"„Doamne, arată-mi sfârşitul meu,"],[5,"Iată, mi-ai făcut zilele lățimi ale mâinilor."],[6,"„Cu siguranță fiecare om merge ca o umbră."],[7,"Acum, Doamne, ce aștept?"],[8,"Eliberează-mă de toate fărădelegile mele."],[9,"Eram mut."],[10,"Îndepărtează-ți flagelul de lângă mine."],[11,"Când mustri și îndrepți pe om pentru nelegiuire,"],[12,"„Ascultă, Doamne, rugăciunea mea, și ascultă strigătul meu."],[13,"O, scutește-mă, ca să-mi revin putere,"]]],[40,[[1,"L-am așteptat cu răbdare pe Domnul."],[2,"M-a scos și pe mine dintr-o groapă îngrozitoare,"],[3,"El a pus în gura mea un cântec nou, chiar laudă Dumnezeului nostru."],[4,"Ferice de omul care pune în Domnul încrederea lui,"],[5,"Multe, DOAMNE, Dumnezeul meu, sunt lucrările minunate pe care le-ai făcut,"],[6,"Sacrificiul și ofranda pe care nu le-ați dorit."],[7,"Atunci am zis: „Iată, am venit."],[8,"Îmi face plăcere să fac voia Ta, Dumnezeule."],[9,"Am vestit o veste bună a neprihănirii în marea adunare."],[10,"Nu ți-am ascuns dreptatea în inima mea."],[11,"Nu ține de la mine îndurările Tale, Doamne."],[12,"Căci nenumărate rele m-au înconjurat."],[13,"Bucură-te, Doamne, să mă izbăvească."],[14,"Să fie dezamăgiți și dezamăgiți cei care caută sufletul meu să-l distrugă."],[15,"Să fie pustii din cauza rușinii lor care îmi spun: „Aha! Aha!”"],[16,"Să se bucure și să se bucure de tine toți cei ce te caută."],[17,"Dar eu sunt sărac și nevoiaș."]]],[41,[[1,"Ferice de cel ce ia în seamă pe cei săraci."],[2,"Domnul îl va păzi și îl va ține în viață."],[3,"Domnul îl va sprijini pe patul lui de bolnav,"],[4,"Am zis: „Doamne, miluiește-mă!"],[5,"Dușmanii mei vorbesc de rău împotriva mea:"],[6,"Dacă vine să mă vadă, spune minciună."],[7,"Toți cei care mă urăsc șoptesc împreună împotriva mea."],[8,"„O boală rea”, spun ei, „l-a afectat."],[9,"Da, propriul meu prieten familiar, în care am avut încredere,"],[10,"Dar Tu, Doamne, ai milă de mine și înalță-mă,"],[11,"Prin aceasta știu că te bucuri de mine,"],[12,"Cât despre mine, tu mă susții în integritatea mea,"],[13,"Binecuvântat să fie Domnul, Dumnezeul lui Israel,"]]],[42,[[1,"Așa cum căprioarele pantaloniesc după pâraiele de apă,"],[2,"Sufletul meu este însetat după Dumnezeu, după Dumnezeul cel viu."],[3,"Lacrimile mele au fost hrana mea zi și noapte,"],[4,"Aceste lucruri îmi aduc aminte și îmi revars sufletul în mine,"],[5,"De ce ești disperat, suflete?"],[6,"Doamne, sufletul meu este în deznădejde în mine."],[7,"Adîncul cheamă la adânc la zgomotul cascadelor tale."],[8,"Domnul va porunci bunătatea Lui în timpul zilei."],[9,"Îl voi întreba pe Dumnezeu, stânca mea: „De ce m-ai uitat?"],[10,"Ca cu o sabie în oasele mele, potrivnicii mei mă ocărănesc,"],[11,"De ce ești disperat, suflete?"]]],[43,[[1,"Justifică-mă, Doamne, și pledează cauza mea împotriva unui neam nelegiuit."],[2,"Căci tu ești Dumnezeul puterii mele. De ce m-ai respins?"],[3,"O, trimite-ți lumina și adevărul tău."],[4,"Atunci mă voi duce la altarul lui Dumnezeu,"],[5,"De ce ești disperat, suflete?"]]],[44,[[1,"Am auzit cu urechile noastre, Doamne;"],[2,"Ai alungat neamurile cu mâna ta,"],[3,"Căci ei nu au luat țara în stăpânire prin propria lor sabie,"],[4,"Doamne, tu ești regele meu."],[5,"Prin tine, ne vom împinge pe adversarii noștri."],[6,"Căci nu mă voi încrede în arcul meu,"],[7,"Dar tu ne-ai izbăvit de potrivnicii noștri,"],[8,"În Dumnezeu ne-am lăudat toată ziua."],[9,"Dar acum ne-ai lepădat și ne-ai adus la necinste,"],[10,"Ne faci să ne întoarcem de la adversar."],[11,"Ne-ai făcut ca niște oi pentru mâncare,"],[12,"Îți vinzi oamenii pentru nimic,"],[13,"Tu ne faci un reproș pentru vecinii noștri,"],[14,"Tu ne faci o vorbă între neamuri,"],[15,"Toată ziua dezonoarea mea este înaintea mea,"],[16,"la batjocura celui care reproșează și abuzează verbal,"],[17,"Toate acestea au venit asupra noastră,"],[18,"Inima noastră nu s-a întors înapoi,"],[19,"deși ne-ai zdrobit în bântuirea șacalilor,"],[20,"Dacă am uitat numele Dumnezeului nostru,"],[21,"nu va cerceta Dumnezeu asta?"],[22,"Da, de dragul tău suntem uciși toată ziua."],[23,"Trezeşte-te!"],[24,"De ce-ți ascunzi fața,"],[25,"Căci sufletul nostru este plecat până în ţărână."],[26,"Ridică-te să ne ajuți."]]],[45,[[1,"Inima mea debordează cu o temă nobilă."],[2,"Sunteți cel mai excelent dintre fiii oamenilor."],[3,"Pune-ți sabia pe coapsă, o, puternic,"],[4,"În măreția ta, călărește biruitor în numele adevărului, smereniei și dreptății."],[5,"Săgețile tale sunt ascuțite."],[6,"Tronul tău, Doamne, este în vecii vecilor."],[7,"Ai iubit dreptatea și ai urât răutatea."],[8,"Toate hainele tale miroase a smirnă, aloe și cassia."],[9,"Fiicele de regi sunt printre femeile voastre onorabile."],[10,"Ascultă, fiică, gândește-te și întoarce-ți urechea."],[11,"Deci regele va dori frumusețea ta,"],[12,"Fiica Tirului vine cu un cadou."],[13,"Prințesa din interior este toată glorioasă."],[14,"Ea va fi condusă la rege în lucrare de brodat."],[15,"Cu bucurie și veselie vor fi conduși."],[16,"Fiii tăi vor lua locul părinților tăi."],[17,"Voi face ca numele tău să fie amintit în toate generațiile."]]],[46,[[1,"Dumnezeu este refugiul și puterea noastră,"],[2,"De aceea nu ne vom teme, deși pământul se va schimba,"],[3,"deși apele lui urlă și sunt tulburate,"],[4,"Există un râu, ale cărui pâraie bucură cetatea lui Dumnezeu,"],[5,"Dumnezeu este în ea. Ea nu va fi mișcată."],[6,"Națiunile au înfuriat. Regatele au fost mutate."],[7,"Domnul armatelor este cu noi."],[8,"Vino, vezi lucrările Domnului,"],[9,"El face să înceteze războaiele până la capătul pământului."],[10,"„Fii liniştit şi ştii că Eu sunt Dumnezeu."],[11,"Domnul armatelor este cu noi."]]],[47,[[1,"O, bateți din palme, toate națiunile."],[2,"Căci Domnul Prea Înalt este înfricoșător."],[3,"El supune neamurile sub noi,"],[4,"El ne alege moștenirea pentru noi,"],[5,"Dumnezeu a urcat cu un strigăt,"],[6,"Cântați laude lui Dumnezeu! Cântați laude!"],[7,"Căci Dumnezeu este Regele întregului pământ."],[8,"Dumnezeu domnește peste națiuni."],[9,"Prinții popoarelor sunt adunați împreună,"]]],[48,[[1,"Mare este DOMNUL și mult de lăudat,"],[2,"Frumos în înălțime, bucuria întregului pământ,"],[3,"Dumnezeu s-a arătat în cetățile ei ca un refugiu."],[4,"Căci, iată, regii s-au adunat,"],[5,"Au văzut-o, apoi au rămas uimiți."],[6,"Tremurul i-a apucat acolo,"],[7,"Cu vântul de răsărit, spargi corăbiile din Tarsis."],[8,"După cum am auzit, așa am văzut,"],[9,"Ne-am gândit la bunătatea ta iubitoare, Doamne,"],[10,"Cum este numele tău, Doamne,"],[11,"Să se bucure muntele Sionului!"],[12,"Umblă prin Sion și ocolește-o."],[13,"Observați bastionurile ei."],[14,"Căci acest Dumnezeu este Dumnezeul nostru în vecii vecilor."]]],[49,[[1,"Auziți asta, popoarelor tuturor."],[2,"atât scăzut cât și ridicat,"],[3,"Gura mea va rosti cuvinte de înțelepciune."],[4,"Îmi voi înclina urechea spre un proverb."],[5,"De ce să mă tem în zilele răului,"],[6,"Cei care au încredere în averea lor,"],[7,"niciunul dintre ei nu-și poate răscumpăra în niciun fel fratele,"],[8,"Căci răscumpărarea vieții lor este costisitoare,"],[9,"ca să trăiască pentru totdeauna,"],[10,"Căci vede că oamenii înțelepți mor;"],[11,"Gândul lor lăuntric este că casele lor vor dăinui pentru totdeauna,"],[12,"Dar omul, în ciuda bogățiilor sale, nu rezistă."],[13,"Acesta este destinul celor proști,"],[14,"Ei sunt desemnați ca o turmă pentru Sheol."],[15,"Dar Dumnezeu îmi va izbăvi sufletul din puterea mormântului,"],[16,"Nu te teme când un om se îmbogățește,"],[17,"căci când va muri nu va duce nimic."],[18,"Deși în timp ce a trăit și-a binecuvântat sufletul..."],[19,"el va merge la neamul părinţilor săi."],[20,"Un om care are bogății fără înțelegere,"]]],[50,[[1,"Cel Puternic, Dumnezeu, Domnul, vorbește,"],[2,"Din Sion, desăvârșirea frumuseții,"],[3,"Dumnezeul nostru vine și nu tăce."],[4,"El cheamă la ceruri de sus,"],[5,"„Adună la mine sfinții mei,"],[6,"Cerurile vor vesti dreptatea Lui,"],[7,"„Ascultă, poporul meu, și voi vorbi."],[8,"Nu te mustr pentru sacrificiile tale."],[9,"Nu am nevoie de un taur de la taraba ta,"],[10,"Căci fiecare animal al pădurii este al meu,"],[11,"Cunosc toate păsările munților."],[12,"Dacă mi-ar fi foame, nu ți-aș spune,"],[13,"Voi mânca carnea taurilor,"],[14,"Oferiți lui Dumnezeu jertfa de mulțumire."],[15,"Cheamă-mă în ziua necazului."],[16,"Dar celui rău Dumnezeu le spune:"],[17,"pentru că urăști instruirea,"],[18,"Când ai văzut un hoț, ai fost de acord cu el,"],[19,"„Îți dai gura răului."],[20,"Stai și vorbești împotriva fratelui tău."],[21,"Tu ai făcut aceste lucruri, iar eu am tăcut."],[22,"„Acum, gândiți-vă la aceasta, cei care L-ați uitat pe Dumnezeu,"],[23,"Cine aduce jertfa de mulțumire mă slăvește pe mine,"]]],[51,[[1,"Miluiește-mă, Doamne, după bunătatea Ta iubitoare."],[2,"Spală-mă bine de nelegiuirea mea."],[3,"Căci îmi cunosc fărădelegile."],[4,"Împotriva ta, și numai împotriva ta, am păcătuit,"],[5,"Iată, m-am născut în nelegiuire."],[6,"Iată, tu dorești adevărul în părțile lăuntrice."],[7,"Purifică-mă cu isop și voi fi curat."],[8,"Lasă-mă să aud bucurie și bucurie,"],[9,"Ascunde-ți fața de păcatele mele,"],[10,"Fă în mine o inimă curată, Doamne."],[11,"Nu mă arunca din prezența ta,"],[12,"Dă-mi bucuria mântuirii tale."],[13,"Atunci îi voi învăţa pe cei fărădelege căile tale."],[14,"Izbăvește-mă de vina vărsării de sânge, Dumnezeule, Dumnezeul mântuirii mele."],[15,"Doamne, deschide-mi buzele."],[16,"Căci tu nu te bucuri de sacrificii, altfel ți-l dau."],[17,"Jertfele lui Dumnezeu sunt un duh zdrobit."],[18,"Faceți bine în binele voastră Sionului."],[19,"Atunci te vei bucura de jertfele dreptății,"]]],[52,[[1,"De ce te lauzi cu răutăți, omule puternic?"],[2,"Limba ta plănuiește distrugerea,"],[3,"Iubești răul mai mult decât binele,"],[4,"Iubești toate cuvintele devoratoare,"],[5,"De asemenea, Dumnezeu te va distruge pentru totdeauna."],[6,"Și cei drepți o vor vedea și se vor teme,"],[7,"„Iată, acesta este omul care nu a făcut din Dumnezeu puterea lui,"],[8,"Dar în ceea ce mă privește, sunt ca un măslin verde în casa lui Dumnezeu."],[9,"Îți voi mulțumi pentru totdeauna, pentru că ai făcut-o."]]],[53,[[1,"Nebunul a spus în inima lui: „Nu există Dumnezeu”."],[2,"Dumnezeu se uită din cer la copiii oamenilor,"],[3,"Fiecare dintre ei s-a întors."],[4,"Să nu aibă știință lucrătorii fărădelegii,"],[5,"Acolo erau cu mare frică, unde nu era frică,"],[6,"O, dacă ar veni mântuirea lui Israel din Sion!"]]],[54,[[1,"Mântuiește-mă, Doamne, pe numele tău."],[2,"Ascultă-mi rugăciunea, Doamne."],[3,"Căci străini s-au ridicat împotriva mea."],[4,"Iată, Dumnezeu este ajutorul meu."],[5,"El va răsplăti răul dușmanilor mei."],[6,"Cu o ofrandă de voință liberă, vă voi sacrifica."],[7,"Căci m-a izbăvit din orice necaz."]]],[55,[[1,"Ascultă-mi rugăciunea, Doamne."],[2,"Fii atent la mine și răspunde-mi."],[3,"din cauza vocii dușmanului,"],[4,"Inima mă doare puternic în mine."],[5,"Înfricoșarea și tremurul au venit asupra mea."],[6,"Am spus: „Oh, dacă aș avea aripi ca un porumbel!"],[7,"Iată, atunci aș rătăci departe."],[8,"„M-aș grăbi la un adăpost de vântul și furtună.”"],[9,"Încurcă-i, Doamne, și încurcă-le limbajul,"],[10,"Zi și noapte ei se plimbă pe pereții lui."],[11,"Forțele distructive sunt în ea."],[12,"Căci nu un dușman m-a insultat,"],[13,"Dar ai fost tu, un bărbat ca mine,"],[14,"Am avut o părtășie dulce împreună."],[15,"Lasă moartea să vină brusc asupra lor."],[16,"Cât despre mine, voi chema pe Dumnezeu."],[17,"Seara, dimineața și la amiază, voi striga în necaz."],[18,"El mi-a izbăvit în pace sufletul din lupta care a fost împotriva mea,"],[19,"Dumnezeu, care este întronat în veci,"],[20,"Își ridică mâinile împotriva prietenilor săi."],[21,"Gura îi era netedă ca untul,"],[22,"Aruncă-ți povara asupra Domnului și el te va sprijini."],[23,"Dar Tu, Dumnezeule, îi vei coborî în groapa distrugerii."]]],[56,[[1,"Fii milostiv cu mine, Doamne, căci omul vrea să mă înghită."],[2,"Dușmanii mei vor să mă înghită toată ziua,"],[3,"Când îmi este frică,"],[4,"În Dumnezeu, laud cuvântul Lui."],[5,"Toată ziua îmi întorc cuvintele."],[6,"Ei conspira și pândesc,"],[7,"Vor scăpa ei prin nelegiuire?"],[8,"Tu numări rătăcirile mele."],[9,"Atunci vrăjmașii mei se vor întoarce înapoi în ziua în care voi chema."],[10,"În Dumnezeu, voi lăuda cuvântul Lui."],[11,"Mi-am pus încrederea în Dumnezeu."],[12,"Jurămintele tale sunt asupra mea, Doamne."],[13,"Căci mi-ai izbăvit sufletul de la moarte,"]]],[57,[[1,"Fii milostiv cu mine, Doamne, fii milostiv cu mine,"],[2,"strig către Dumnezeu Preaînalt,"],[3,"El va trimite din cer și mă va mântui,"],[4,"Sufletul meu este printre lei."],[5,"Înălță-te, Doamne, mai presus de ceruri!"],[6,"Au pregătit o plasă pentru pașii mei."],[7,"Inima mea este neclintită, Doamne."],[8,"Trezește-te, slava mea! Trezește-te, lăută și harpă!"],[9,"Îți voi mulțumi, Doamne, printre popoare."],[10,"Căci marea ta bunătate iubitoare ajunge până la ceruri,"],[11,"Înălță-te, Doamne, mai presus de ceruri."]]],[58,[[1,"Vorbiți cu adevărat dreptate, tăcuți?"],[2,"Nu, în inima ta plănuiești nedreptate."],[3,"Cei răi se rătăcesc din pântece."],[4,"Otrava lor este ca otrava unui șarpe,"],[5,"care nu ascultă vocea fermecătoarelor,"],[6,"Rupe-le dinții, Doamne, în gură."],[7,"Lasă-le să dispară ca apa care curge."],[8,"Să fie ca un melc care se topește și trece,"],[9,"Înainte ca oalele tale să simtă căldura spinilor,"],[10,"Cel drept se va bucura când va vedea răzbunarea."],[11,"astfel încât oamenii să zică: „Cu siguranță, este o răsplată pentru cei drepți."]]],[59,[[1,"Izbăvește-mă de dușmanii mei, Dumnezeul meu."],[2,"Izbăvește-mă de lucrătorii fărădelegii."],[3,"Căci, iată, ei stau la pândă pentru sufletul meu."],[4,"Nu am greșit, dar ei sunt gata să mă atace."],[5,"Tu, Doamne, Dumnezeul oștirilor, Dumnezeul lui Israel,"],[6,"Se întorc seara, urlând ca câinii,"],[7,"Iată, ei văipă cu gura."],[8,"Dar tu, Doamne, râzi de ei."],[9,"O, puterea mea, te privesc,"],[10,"Dumnezeul meu va merge înaintea mea cu bunătatea Sa iubitoare."],[11,"Nu-i ucide, altfel oamenii mei ar putea uita."],[12,"Pentru păcatul gurii lor și cuvintele buzelor lor,"],[13,"Consumă-le cu mânie."],[14,"Seara lasă-i să se întoarcă."],[15,"Ei vor rătăci în sus și în jos după mâncare,"],[16,"Dar voi cânta puterea ta."],[17,"Ție, puterea mea, voi cânta laude."]]],[60,[[1,"Doamne, ne-ai respins."],[2,"Ai făcut pământul să tremure."],[3,"Le-ai arătat oamenilor tăi lucruri grele."],[4,"Le-ai dat steag celor ce se tem de tine,"],[5,"Pentru ca iubitul tău să fie izbăvit,"],[6,"Dumnezeu a vorbit din sanctuarul Său:"],[7,"Galaad este al meu și Manase este al meu."],[8,"Moab este chiuveta mea."],[9,"Cine mă va aduce în orașul puternic?"],[10,"Doamne, nu ne-ai respins?"],[11,"Dă-ne ajutor împotriva adversarului,"],[12,"Prin Dumnezeu vom face viteji,"]]],[61,[[1,"Ascultă-mi strigătul, Doamne."],[2,"De la capătul pământului, te voi chema când inima mea va fi copleșită."],[3,"Căci ai fost un refugiu pentru mine,"],[4,"Voi locui în cortul tău pentru totdeauna."],[5,"Căci Tu, Doamne, mi-ai auzit jurămintele."],[6,"Vei prelungi viața regelui."],[7,"El va fi tronat în prezența lui Dumnezeu pentru totdeauna."],[8,"Așa că voi cânta lauda pentru totdeauna numelui tău,"]]],[62,[[1,"Sufletul meu se odihnește numai în Dumnezeu."],[2,"El singur este stânca mea, mântuirea mea și fortăreața mea."],[3,"Cât timp vei ataca un bărbat?"],[4,"Ei intenționează pe deplin să-l arunce jos din locul lui înalt."],[5,"Suflete al meu, așteaptă în tăcere numai pe Dumnezeu,"],[6,"El singur este stânca mea și mântuirea mea, fortăreața mea."],[7,"Mântuirea și cinstea mea sunt la Dumnezeu."],[8,"Aveți încredere în el în orice moment, oameni buni."],[9,"Cu siguranță bărbații de grad scăzut sunt doar o suflare,"],[10,"Nu ai încredere în opresiune."],[11,"Dumnezeu a vorbit o dată;"],[12,"Și Ție, Doamne, îți aparține bunătatea iubitoare,"]]],[63,[[1,"Doamne, tu ești Dumnezeul meu."],[2,"Deci te-am văzut în sanctuar,"],[3,"Pentru că bunătatea ta iubitoare este mai bună decât viața,"],[4,"Așa că te voi binecuvânta cât voi trăi."],[5,"Sufletul meu va fi săturat ca cu cea mai bogată mâncare."],[6,"când îmi amintesc de tine în patul meu,"],[7,"Căci tu ai fost ajutorul meu."],[8,"Sufletul meu rămâne aproape de tine."],[9,"Dar cei care caută sufletul meu să-l distrugă"],[10,"Ei vor fi predați puterii sabiei."],[11,"Dar regele se va bucura de Dumnezeu."]]],[64,[[1,"Ascultă-mi vocea, Doamne, în plângerea mea."],[2,"Ascunde-mă de uneltirea celor răi,"],[3,"care își ascuți limba ca o sabie,"],[4,"să împuște oameni nevinovați din ambuscadă."],[5,"Ei se încurajează în planuri rele."],[6,"Ei complotează nedreptate, spunând: „Am făcut un plan perfect!”"],[7,"Dar Dumnezeu va trage în ei."],[8,"Limbile lor îi vor ruina."],[9,"Întreaga omenire se va teme."],[10,"Cei neprihăniți se vor veseli în Domnul,"]]],[65,[[1,"Lauda te așteaptă, Doamne, în Sion."],[2,"Tu care asculți rugăciunea,"],[3,"Păcatele m-au copleșit,"],[4,"Binecuvântat este cel pe care îl alegi și îl faci să se apropie,"],[5,"Prin fapte minunate de dreptate, ne răspunzi,"],[6,"Prin puterea ta, tu formați munții,"],[7,"Tu încă vuietul mărilor,"],[8,"Și cei care locuiesc în locuri îndepărtate se tem de minunile tale."],[9,"Vizitați pământul și îl udați."],[10,"Îi umezi brazdele."],[11,"Încoronați anul cu recompensă."],[12,"Pajiștile sălbatice se revarsă."],[13,"Pășunile sunt acoperite cu turme."]]],[66,[[1,"Fă un strigăt de bucurie către Dumnezeu, tot pământul!"],[2,"Cântați pentru slava numelui Lui!"],[3,"Spune-i lui Dumnezeu: „Cât de minunate sunt faptele tale!"],[4,"Tot pământul ți se va închina,"],[5,"Vino și vezi faptele lui Dumnezeu -"],[6,"El a transformat marea în uscat."],[7,"El stăpânește prin puterea lui pentru totdeauna."],[8,"Lăudați pe Dumnezeul nostru, popoare!"],[9,"care ne păstrează viața printre cei vii,"],[10,"Căci Tu, Doamne, ne-ai pus la încercare."],[11,"Ne-ai adus la închisoare."],[12,"Ai permis bărbaților să călătorească peste capetele noastre."],[13,"Voi intra în templul tău cu arderi de tot."],[14,"pe care buzele mele mi-au promis,"],[15,"Vă voi aduce arderi de tot de animale grase,"],[16,"Veniți și ascultați, toți cei care vă temeți de Dumnezeu."],[17,"I-am strigat cu gura."],[18,"Dacă am prețuit păcatul în inima mea,"],[19,"Dar, cu siguranță, Dumnezeu a ascultat."],[20,"Binecuvântat să fie Dumnezeu, care nu mi-a abătut rugăciunea,"]]],[67,[[1,"Dumnezeu să ne fie milostiv, să ne binecuvânteze,"],[2,"Pentru ca calea Ta să fie cunoscută pe pământ,"],[3,"popoarele să Te laude, Doamne."],[4,"O, să se bucure neamurile și să cânte de bucurie,"],[5,"Să Te laude popoarele, Doamne."],[6,"Pământul și-a dat sporul."],[7,"Dumnezeu ne va binecuvânta."]]],[68,[[1,"Să se ridice Dumnezeu!"],[2,"Pe măsură ce fumul este alungat,"],[3,"Dar cei drepți să se bucure."],[4,"Cântați lui Dumnezeu! Cântați laude numelui lui!"],[5,"Un tată al orfanilor și un apărător al văduvelor,"],[6,"Dumnezeu îi pune pe cei singuri în familii."],[7,"Doamne, când ai ieșit înaintea poporului tău,"],[8,"Pământul tremura."],[9,"Tu, Doamne, ai trimis o ploaie abundentă."],[10,"Adunarea ta a locuit acolo."],[11,"Domnul a vestit cuvântul."],[12,"\"Regii armatelor fug! Ei fug!\""],[13,"în timp ce dormi printre focurile de tabără,"],[14,"Când Atotputernicul a împrăștiat regi în ea,"],[15,"Munții Basanului sunt munți maiestuoși."],[16,"De ce te uiți cu invidie, munți aspre,"],[17,"Carele lui Dumnezeu sunt zeci de mii și mii de mii."],[18,"Ai urcat pe sus."],[19,"Binecuvântat să fie Domnul, care ne poartă zilnic poverile,"],[20,"Dumnezeu este pentru noi un Dumnezeu al eliberării."],[21,"Dar Dumnezeu va lovi capul dușmanilor Săi,"],[22,"Domnul a zis: „Te voi aduce înapoi din Basan,"],[23,"ca să-i zdrobești, scufundându-ți piciorul în sânge,"],[24,"Au văzut procesiunile tale, Doamne,"],[25,"Cântăreții mergeau înainte, menestrelii urmau după,"],[26,"„Binecuvântați pe Dumnezeu în adunări,"],[27,"Este micul Beniamin, conducătorul lor,"],[28,"Dumnezeul tău a poruncit puterea ta."],[29,"Din cauza templului tău din Ierusalim,"],[30,"Certe animalul sălbatic al stufului,"],[31,"Prinții vor ieși din Egipt."],[32,"Cântați lui Dumnezeu, împărății ale pământului!"],[33,"celui ce călărește pe cerurile cerurilor, care sunt din vechime;"],[34,"Atribuiți putere lui Dumnezeu!"],[35,"Ești minunat, Doamne, în sanctuarele tale."]]],[69,[[1,"Salvează-mă, Doamne,"],[2,"Mă scufund în mocirla adâncă, unde nu există punct de sprijin."],[3,"Sunt obosit de plânsul meu."],[4,"Cei care mă urăsc fără motiv sunt mai mult decât părul capului meu."],[5,"Doamne, știi nebunia mea."],[6,"Nu lăsa să fie de rușine prin mine cei care te așteaptă, Doamne, Doamne al armatelor."],[7,"Pentru că, de dragul tău, am suportat ocară."],[8,"Am devenit străin pentru frații mei,"],[9,"Căci râvna casei tale mă mistuie."],[10,"Când am plâns și am postit,"],[11,"Când mi-am făcut haina de sac,"],[12,"Cei care stau în poartă vorbesc despre mine."],[13,"Dar în ceea ce mă privește, rugăciunea mea este către Tine, Doamne, într-un timp binevenit."],[14,"Scoate-mă din noroi și nu mă lăsa să mă scufund."],[15,"Nu lăsa apele potopului să mă copleșească,"],[16,"Răspunde-mi, Doamne, căci bunătatea Ta este bună."],[17,"Nu-ți ascunde fața de slujitorul tău,"],[18,"Apropie-te de sufletul meu și mântuiește-l."],[19,"Tu cunoști ocara mea, rușinea și dezonoarea mea."],[20,"Ocara mi-a frânt inima și sunt plin de greutate."],[21,"Mi-au dat și otravă pentru mâncare."],[22,"Lasă masa lor dinaintea lor să devină o cursă."],[23,"Lasă-le ochii să se întunece, ca să nu poată vedea."],[24,"Revarsă-ți indignarea asupra lor."],[25,"Să le fie locuința pustie."],[26,"Căci ei îl prigonesc pe cel pe care l-aţi rănit."],[27,"Acuzați-i de crimă peste crimă."],[28,"Să fie șters din cartea vieții,"],[29,"Dar sunt în durere și suferință."],[30,"Voi lăuda numele lui Dumnezeu cu un cântec,"],[31,"Îi va plăcea Domnului mai mult decât un bou,"],[32,"Cei smeriți au văzut asta și sunt bucuroși."],[33,"Căci Domnul aude pe cei nevoiași,"],[34,"Să-l laude cerul și pământul;"],[35,"Căci Dumnezeu va mântui Sionul și va zidi cetățile lui Iuda."],[36,"De asemenea, copiii slujitorilor lui o vor moșteni."]]],[70,[[1,"Grăbește-te, Doamne, să mă eliberezi."],[2,"Să fie dezamăgiți și derutați cei care îmi caută sufletul."],[3,"Să se întoarcă din cauza rușinii lor"],[4,"Să se bucure și să se bucure de tine toți cei ce te caută."],[5,"Dar eu sunt sărac și nevoiaș."]]],[71,[[1,"În Tine, Doamne, mă adăpostesc."],[2,"Eliberează-mă în dreptatea Ta și mântuiește-mă."],[3,"Fii pentru mine o stâncă de refugiu la care să merg mereu."],[4,"Izbăvește-mă, Dumnezeul meu, din mâna celor răi,"],[5,"Căci Tu ești nădejdea mea, Doamne,"],[6,"M-am bazat pe tine din pântece."],[7,"Sunt o minune pentru mulți,"],[8,"Gura mea se va umple de lauda Ta,"],[9,"Nu mă respinge la bătrânețe."],[10,"Căci dușmanii mei vorbesc despre mine."],[11,"spunând: „Dumnezeu l-a părăsit."],[12,"Doamne, nu fi departe de mine."],[13,"Lasă acuzatorii mei să fie dezamăgiți și consumați."],[14,"Dar voi spera mereu,"],[15,"Gura mea va spune despre dreptatea ta,"],[16,"Voi veni cu faptele puternice ale Domnului Iehova."],[17,"Doamne, tu m-ai învățat din tinerețe."],[18,"Da, chiar și când voi fi bătrân și cărunt, Doamne, nu mă părăsi,"],[19,"Doamne, dreptatea Ta ajunge și până la ceruri."],[20,"Tu, care ne-ai arătat necazuri multe și amare,"],[21,"Mărește-mi onoarea"],[22,"Te voi lăuda și cu harpa pentru credincioșia ta, Dumnezeul meu."],[23,"Buzele mele vor striga de bucurie!"],[24,"Limba mea va vorbi toată ziua despre dreptatea ta,"]]],[72,[[1,"Doamne, dă-i împăratului dreptatea ta;"],[2,"El va judeca poporul tău cu dreptate,"],[3,"Munții vor aduce prosperitate oamenilor."],[4,"El îi va judeca pe săracii poporului."],[5,"Se vor teme de tine cât timp soarele va răbda;"],[6,"El va coborî ca ploaia pe iarba cosită,"],[7,"În zilele lui, cei neprihăniți vor înflori,"],[8,"El va stăpâni și de la mare la mare,"],[9,"Cei care locuiesc în pustie se vor închina înaintea lui."],[10,"Împărații Tarsis și ai insulelor vor aduce tribut."],[11,"Da, toți împărații vor cădea înaintea lui."],[12,"Căci el va izbăvi pe cei nevoiași când strigă;"],[13,"El va avea milă de cei săraci și nevoiași."],[14,"El le va izbăvi sufletul de asuprire și violență."],[15,"El va trăi; și aurul lui Seba i se va da."],[16,"Abundența de cereale va fi în toată țara."],[17,"Numele lui rămâne pentru totdeauna."],[18,"Lăudat să fie Domnul Dumnezeu, Dumnezeul lui Israel,"],[19,"Binecuvântat să fie numele Lui glorios în veci!"],[20,"Astfel se încheie rugăciunile lui David, fiul lui Isai."]]],[73,[[1,"Cu siguranță Dumnezeu este bun cu Israel,"],[2,"Dar în ceea ce mă privește, picioarele îmi erau aproape dispărute."],[3,"Căci eram invidios pe cei aroganți,"],[4,"Căci nu există lupte în moartea lor,"],[5,"Ei sunt liberi de poverile oamenilor,"],[6,"Prin urmare, mândria este ca un lanț în jurul gâtului lor."],[7,"Ochii li se umflă de grăsime."],[8,"Își bat joc și vorbesc cu răutate."],[9,"Și-au pus gura în ceruri."],[10,"De aceea oamenii lor se întorc la ei,"],[11,"Ei spun: „De unde știe Dumnezeu?"],[12,"Iată, aceștia sunt cei răi."],[13,"Cu siguranță mi-am curățat inima în zadar,"],[14,"Toată ziua am fost chinuit,"],[15,"Dacă aș fi spus: „Voi vorbi așa”,"],[16,"Când am încercat să înțeleg asta,"],[17,"până am intrat în sanctuarul lui Dumnezeu,"],[18,"Cu siguranță le-ai așezat în locuri alunecoase."],[19,"Cum sunt distruși dintr-o dată!"],[20,"Ca un vis când te trezești,"],[21,"Căci sufletul meu era întristat."],[22,"Eram atât de nesimțit și ignorant."],[23,"Cu toate acestea, sunt continuu cu tine."],[24,"Mă vei călăuzi cu sfatul tău,"],[25,"Pe cine am în rai?"],[26,"Carnea și inima mea slăbesc,"],[27,"Căci, iată, cei care sunt departe de tine vor pieri."],[28,"Dar este bine pentru mine să mă apropii de Dumnezeu."]]],[74,[[1,"Doamne, de ce ne-ai respins pentru totdeauna?"],[2,"Adu-ți aminte de adunarea ta, pe care ai cumpărat-o din vechime,"],[3,"Ridică-ți picioarele spre ruinele perpetue,"],[4,"Vrăjmașii tăi au răcnit în mijlocul adunării tale."],[5,"S-au comportat ca niște oameni care mânuiau secure,"],[6,"Acum îi sparg toată lucrarea cioplită cu secure și ciocane."],[7,"Au ars sanctuarul tău până la pământ."],[8,"Ei au spus în inima lor: „Îi vom zdrobi complet”."],[9,"Nu vedem semne miraculoase."],[10,"Până când, Doamne, va reproșa potrivnicul?"],[11,"De ce îți tragi mâna înapoi, chiar și mâna dreaptă?"],[12,"Dar Dumnezeu este Regele meu din vechime,"],[13,"Ai împărțit marea cu puterea ta."],[14,"Ai rupt capetele lui Leviatan în bucăți."],[15,"Ai deschis izvorul și pârâul."],[16,"Ziua este a ta, noaptea este și a ta."],[17,"Tu ai stabilit toate hotarele pământului."],[18,"Adu-ți aminte că vrăjmașul te-a batjocorit, Doamne."],[19,"Nu preda sufletul porumbelului tău fiarelor sălbatice."],[20,"Onorează-ți legământul,"],[21,"Nu-i lăsa pe cei asupriți să se întoarcă rușinat."],[22,"Ridică-te, Doamne! Pledează-ți propria cauză."],[23,"Nu uita de vocea adversarilor tăi."]]],[75,[[1,"Îți mulțumim, Doamne."],[2,"Când aleg ora stabilită,"],[3,"Pământul și toți locuitorii lui se cutremură."],[4,"Le-am spus aroganților: „Nu vă lăudați!”"],[5,"Nu ridica cornul sus."],[6,"Căci nici de la răsărit, nici de la apus,"],[7,"Dar Dumnezeu este judecătorul."],[8,"Căci în mâna Domnului este un pahar,"],[9,"Dar voi declara asta pentru totdeauna:"],[10,"Voi tăia toate coarnele celor răi,"]]],[76,[[1,"În Iuda, Dumnezeu este cunoscut."],[2,"Cortul lui se află și în Salem."],[3,"Acolo a spart săgețile în flăcări ale arcului,"],[4,"Glorios ești și excelent,"],[5,"Oameni curajoși zac jefuiți,"],[6,"La mustrarea ta, Dumnezeul lui Iacov,"],[7,"Tu, chiar și tu, ești de temut."],[8,"Tu ai pronunțat judecata din ceruri."],[9,"când Dumnezeu s-a ridicat la judecată,"],[10,"Cu siguranță mânia omului te laudă."],[11,"Fă jurăminte Domnului Dumnezeului tău și împlinește-le!"],[12,"El va tăia spiritul prinților."]]],[77,[[1,"Strigătul meu merge către Dumnezeu!"],[2,"În ziua necazului meu, am căutat pe Domnul."],[3,"Îmi amintesc de Dumnezeu și gemu."],[4,"Îmi ții pleoapele deschise."],[5,"M-am gândit la zilele de odinioară,"],[6,"Îmi amintesc de cântecul meu noaptea."],[7,"„Ne va lepăda Domnul pentru totdeauna?"],[8,"A dispărut pentru totdeauna bunătatea lui iubitoare?"],[9,"A uitat Dumnezeu să fie milostiv?"],[10,"Apoi m-am gândit: „Voi face apel la asta:"],[11,"Îmi voi aduce aminte de faptele Domnului;"],[12,"De asemenea, voi medita la toată lucrarea ta,"],[13,"Calea Ta, Doamne, este în sanctuar."],[14,"Tu ești Dumnezeul care face minuni."],[15,"Ți-ai răscumpărat poporul cu brațul tău,"],[16,"Te-au văzut apele, Doamne."],[17,"Norii au turnat apă."],[18,"Vocea tunetului tău era în vârtej."],[19,"Drumul tău a fost prin mare,"],[20,"Ai condus poporul tău ca o turmă,"]]],[78,[[1,"Ascultă-mi învăţătura, poporul meu."],[2,"Îmi voi deschide gura într-o pildă."],[3,"pe care le-am auzit și cunoscut,"],[4,"Nu le vom ascunde de copiii lor,"],[5,"Căci a stabilit un legământ în Iacov,"],[6,"pentru ca generația viitoare să cunoască, chiar și copiii care ar trebui să se nască;"],[7,"ca să-și pună nădejdea în Dumnezeu,"],[8,"și s-ar putea să nu fie ca părinții lor -"],[9,"Copiii lui Efraim, fiind înarmați și purtând arcuri,"],[10,"Ei nu au respectat legământul lui Dumnezeu,"],[11,"Au uitat faptele lui,"],[12,"El a făcut lucruri minunate înaintea părinților lor,"],[13,"El a despicat marea și le-a făcut să treacă."],[14,"Ziua îi conducea și cu un nor,"],[15,"El a despicat pietre în pustie,"],[16,"El a scos și pâraie din stâncă,"],[17,"Cu toate acestea, ei au continuat să păcătuiască împotriva lui,"],[18,"L-au ispitit pe Dumnezeu în inima lor"],[19,"Da, au vorbit împotriva lui Dumnezeu."],[20,"Iată, el a lovit stânca și au țâșnit ape,"],[21,"De aceea DOMNUL a auzit și S-a mâniat."],[22,"pentru că nu credeau în Dumnezeu,"],[23,"Dar el a poruncit cerurilor de sus,"],[24,"A plouat mană peste ei să mănânce,"],[25,"Omul a mâncat pâinea îngerilor."],[26,"El a făcut să bată vântul de est pe cer."],[27,"De asemenea, a plouat peste ei carne ca praful,"],[28,"I-a lăsat să cadă în mijlocul taberei lor,"],[29,"Așa că au mâncat și s-au săturat."],[30,"Nu s-au întors de la poftele lor."],[31,"când mânia lui Dumnezeu s-a ridicat împotriva lor,"],[32,"Pentru toate acestea încă au păcătuit,"],[33,"De aceea le-a mistuit zilele în zadar,"],[34,"Când i-a ucis, atunci ei l-au întrebat."],[35,"Și-au amintit că Dumnezeu era stânca lor,"],[36,"Dar l-au măgulit cu gura,"],[37,"Căci inima lor nu era potrivită cu el,"],[38,"Dar el, fiind milostiv, a iertat nelegiuirea și nu i-a nimicit."],[39,"Și-a amintit că nu erau decât trup,"],[40,"De câte ori s-au răzvrătit împotriva lui în pustie,"],[41,"S-au întors din nou și L-au ispitit pe Dumnezeu,"],[42,"Nu și-au amintit mâna lui,"],[43,"cum și-a pus semnele în Egipt,"],[44,"le-a transformat râurile în sânge,"],[45,"El a trimis printre ei roiuri de muște, care le-au devorat;"],[46,"El a dat și sporul lor omizii,"],[47,"El le-a nimicit viile cu grindină,"],[48,"De asemenea, a dat peste vitele lor grindinei,"],[49,"El a aruncat asupra lor înverșunatul mâniei lui,"],[50,"Și-a făcut o cale pentru mânia lui."],[51,"și a lovit pe toți întâii născuți din Egipt,"],[52,"Dar și-a scos propriul popor ca pe oile,"],[53,"El i-a condus în siguranță, ca să nu se teamă,"],[54,"I-a adus la hotarul sanctuarului Său,"],[55,"El a alungat și neamurile dinaintea lor,"],[56,"Totuși au ispitit și s-au răzvrătit împotriva Dumnezeului Prea Înalt,"],[57,"dar s-au întors și s-au comportat cu trădare ca părinții lor."],[58,"Căci l-au provocat la mânie cu înălțimile lor,"],[59,"Când Dumnezeu a auzit aceasta, s-a supărat,"],[60,"încât a părăsit cortul din Silo,"],[61,"și și-a dat puterea în robie,"],[62,"Și-a dat pe poporul său săbiei,"],[63,"Focul i-a mistuit pe tinerii lor."],[64,"Preoții lor au căzut de sabie,"],[65,"Atunci Domnul S-a trezit ca unul din somn,"],[66,"Și-a lovit adversarii pe spate."],[67,"Mai mult, a respins cortul lui Iosif,"],[68,"Dar a ales seminția lui Iuda,"],[69,"Și-a construit sanctuarul ca înălțimile,"],[70,"El l-a ales și pe David, robul său,"],[71,"de la urma oilor care au puii lor,"],[72,"Deci el a fost păstorul lor după integritatea inimii lui,"]]],[79,[[1,"Doamne, națiunile au intrat în moștenirea ta."],[2,"Ei au dat trupurile slujitorilor tăi ca hrană pentru păsările cerului,"],[3,"Ei și-au vărsat sângele ca apa în jurul Ierusalimului."],[4,"Am devenit un reproș pentru vecinii noștri,"],[5,"Cât timp, Doamne?"],[6,"Revarsă-ți mânia asupra neamurilor care nu te cunosc,"],[7,"căci l-au devorat pe Iacov,"],[8,"Nu ține împotriva noastră fărădelegile strămoșilor noștri."],[9,"Ajută-ne, Dumnezeul mântuirii noastre, pentru slava Numelui Tău."],[10,"De ce ar trebui să spună națiunile: „Unde este Dumnezeul lor?”"],[11,"Lasă suspinul prizonierului să vină înaintea ta."],[12,"Dați înapoi vecinilor noștri de șapte ori în sânul lor"],[13,"Deci noi, poporul tău și oile pășunilor tale,"]]],[80,[[1,"Ascultă-ne, Păstorul lui Israel,"],[2,"În fața lui Efraim, Beniamin și Manase, trezește-ți puterea!"],[3,"Întoarce-ne din nou, Doamne."],[4,"Domnul, Dumnezeul armatelor,"],[5,"I-ai hrănit cu pâinea lacrimilor,"],[6,"Ne faci o sursă de ceartă pentru vecinii noștri."],[7,"Întoarce-ne din nou, Dumnezeule armatelor."],[8,"Ai scos o viță de vie din Egipt."],[9,"Ai curățat terenul pentru asta."],[10,"Munții erau acoperiți de umbra ei."],[11,"Și-a trimis ramurile spre mare,"],[12,"De ce i-ai dărâmat zidurile,"],[13,"Mistrețul din lemn îl răvălește."],[14,"Întoarce-te din nou, te rugăm, Dumnezeule armatelor."],[15,"stocul pe care l-a plantat mâna ta dreaptă,"],[16,"Este ars cu foc."],[17,"Mâna ta să fie pe omul din dreapta ta,"],[18,"Deci nu ne vom îndepărta de tine."],[19,"Întoarce-ne din nou, Doamne, Dumnezeul oștirilor."]]],[81,[[1,"Cântați cu voce tare lui Dumnezeu, puterea noastră!"],[2,"Ridică un cântec și adu aici tamburina,"],[3,"Sună din trâmbiță la Luna Nouă,"],[4,"Căci este o lege pentru Israel,"],[5,"El a pus-o în Iosif ca legământ,"],[6,"„I-am scos umărul de povara."],[7,"Ai chemat în necaz și eu te-am izbăvit."],[8,"„Ascultă, poporul Meu, și-ți voi mărturisi,"],[9,"Nu va fi nici un dumnezeu străin în tine,"],[10,"Eu sunt Domnul, Dumnezeul tău,"],[11,"Dar oamenii mei nu mi-au ascultat vocea."],[12,"Așa că i-am lăsat să plece după încăpățânarea inimii lor,"],[13,"O, dacă poporul meu m-ar asculta,"],[14,"În curând le-aș supune dușmanii,"],[15,"Următorii lui Iehova s-ar înfiora înaintea lui,"],[16,"Dar i-ar fi hrănit și cu cel mai bun grâu."]]],[82,[[1,"Dumnezeu prezidează marea adunare."],[2,"„Cât timp vei judeca pe nedrept,"],[3,"„Apără-i pe cei slabi, pe cei săraci și pe orfani."],[4,"Salvați pe cei slabi și nevoiași."],[5,"Ei nu știu, nici nu înțeleg."],[6,"Am spus: „Voi sunteți zei,"],[7,"Totuși vei muri ca oamenii,"],[8,"Scoală-te, Doamne, judecă pământul,"]]],[83,[[1,"Doamne, nu tace."],[2,"Căci, iată, vrăjmașii tăi sunt stârniți."],[3,"Ei conspira cu viclenie împotriva poporului tău."],[4,"„Veniți”, spun ei, „să-i nimicim ca națiune,"],[5,"Căci ei au conspirat împreună cu o singură minte."],[6,"corturile lui Edom și ale ismaeliților;"],[7,"Ghebal, Amon și Amalek;"],[8,"De asemenea, Asiria este alăturată lor."],[9,"Fă-le ca și lui Madian,"],[10,"care a pierit la Endor,"],[11,"Fă-le nobili ca Oreb și Zeeb,"],[12,"care a spus: „Să luăm în stăpânire pășunile lui Dumnezeu”."],[13,"Doamne, fă-i ca niște praf,"],[14,"Ca focul care arde pădurea,"],[15,"deci urmărește-i cu furtuna ta,"],[16,"Umple-le fețele de confuzie,"],[17,"Să fie dezamăgiți și consternați pentru totdeauna."],[18,"ca să știe că tu singur, al cărui nume este Domnul,"]]],[84,[[1,"Cât de frumoase sunt locuințele voastre,"],[2,"Sufletul meu tânjește și chiar leșine după curțile Domnului."],[3,"Da, vrabia și-a găsit o casă,"],[4,"Fericiți cei ce locuiesc în casa ta."],[5,"Fericiți cei a căror putere este în voi,"],[6,"Trecând prin valea Plângerii, ei o fac loc de izvoare."],[7,"Ei merg din putere în putere."],[8,"Doamne, Dumnezeul armatelor, ascultă rugăciunea mea."],[9,"Iată, Dumnezeule scutul nostru,"],[10,"Căci o zi în curțile tale este mai bună decât o mie."],[11,"Căci Domnul Dumnezeu este un soare și un scut."],[12,"Domnul armatelor,"]]],[85,[[1,"Doamne, ai fost favorabil pământului tău."],[2,"Ai iertat nelegiuirea poporului tău."],[3,"Ți-ai luat toată mânia."],[4,"Întoarce-ne, Dumnezeul mântuirii noastre,"],[5,"Vei fi supărat pe noi pentru totdeauna?"],[6,"Nu ne vei reînvia,"],[7,"Arată-ne bunătatea Ta iubitoare, Doamne."],[8,"Voi auzi ce va vorbi Dumnezeu, Domnul,"],[9,"Cu siguranță mântuirea Lui este aproape de cei ce se tem de El,"],[10,"Mila și adevărul se întâlnesc împreună."],[11,"Adevărul izvorăște din pământ."],[12,"Da, Domnul va da ceea ce este bun."],[13,"Dreptatea merge înaintea lui,"]]],[86,[[1,"Ascultă, Doamne, și răspunde-mi,"],[2,"Păstrează-mi sufletul, căci sunt evlavios."],[3,"Fii milostiv cu mine, Doamne,"],[4,"Adu bucurie în sufletul robului tău,"],[5,"Căci Tu, Doamne, ești bun și gata să ierți,"],[6,"Ascultă, Doamne, rugăciunea mea."],[7,"În ziua necazului meu, te voi chema,"],[8,"Nu este nimeni ca tine printre zei, Doamne,"],[9,"Toate neamurile pe care le-ai făcut vor veni și se vor închina înaintea Ta, Doamne."],[10,"Căci ești mare și faci lucruri minunate."],[11,"Învață-mă calea Ta, Doamne."],[12,"Te voi lăuda, Doamne, Dumnezeul meu, din toată inima mea."],[13,"Căci bunătatea ta iubitoare este mare față de mine."],[14,"Doamne, cei mândri s-au ridicat împotriva mea."],[15,"Dar Tu, Doamne, ești un Dumnezeu milostiv și milostiv,"],[16,"Întoarce-te la mine și ai milă de mine!"],[17,"Arată-mi un semn al bunătății tale,"]]],[87,[[1,"Temelia Lui este în munții sfinți."],[2,"Domnul iubește porțile Sionului mai mult decât toate locuințele lui Iacov."],[3,"Despre tine se vorbesc lucruri glorioase, cetate a lui Dumnezeu. Selah."],[4,"Voi consemna pe Rahab și pe Babilon printre cei care mă recunosc."],[5,"Da, despre Sion se va spune: „Acesta și acela s-au născut în ea”;"],[6,"Domnul va socoti, când va scrie popoarele,"],[7,"Cei care cântă la fel ca și cei care dansează spun:"]]],[88,[[1,"Domnul, Dumnezeul mântuirii mele,"],[2,"Lasă rugăciunea mea să intre în prezența ta."],[3,"Căci sufletul meu este plin de necazuri."],[4,"Sunt numărat printre cei care coboară în groapă."],[5,"pus deoparte printre morți,"],[6,"M-ai pus în cea mai de jos groapă,"],[7,"Mânia ta este puternic asupra mea."],[8,"Mi-ai luat prietenii de la mine."],[9,"Ochii mei sunt stinși de durere."],[10,"Le arăți minuni morților?"],[11,"Bunătatea ta iubitoare este declarată în mormânt?"],[12,"Minunile tale sunt făcute cunoscute în întuneric?"],[13,"Dar către Tine, Doamne, am strigat."],[14,"Doamne, de ce respingi sufletul meu?"],[15,"Sunt chinuit și gata să mor din tinerețe în sus."],[16,"Mânia ta aprigă a trecut peste mine."],[17,"Au venit în jurul meu ca apa toată ziua."],[18,"Ai îndepărtat de mine iubitul și prietenul,"]]],[89,[[1,"Voi cânta pentru totdeauna bunătatea iubitoare a Domnului."],[2,"Într-adevăr, declar: „Dragostea rămâne fermă pentru totdeauna."],[3,"„Am făcut un legământ cu alesul meu,"],[4,"„Voi întemeia progenitul tău pentru totdeauna,"],[5,"Cerurile vor lăuda minunile Tale, Doamne,"],[6,"Căci cine din ceruri poate fi asemănător cu Domnul?"],[7,"un Dumnezeu foarte înfricoșător în soborul sfinților,"],[8,"Doamne, Dumnezeul armatelor, cine este un puternic, ca tine?"],[9,"Tu conduci mândria mării."],[10,"Ai făcut bucăți pe Rahab, ca pe unul dintre cei uciși."],[11,"Cerurile sunt ale tale."],[12,"Tu ai creat nordul și sudul."],[13,"Ai un braț puternic."],[14,"Dreptatea și dreptatea sunt temelia tronului tău."],[15,"Fericiți oamenii care învață să te aclame."],[16,"În numele tău ei se bucură toată ziua."],[17,"Căci tu ești slava puterii lor."],[18,"Căci scutul nostru este al Domnului,"],[19,"Atunci ai vorbit în vedenie sfinților tăi,"],[20,"L-am găsit pe David, servitorul meu."],[21,"cu care mâna mea va fi întărită."],[22,"Niciun dușman nu-l va impozita."],[23,"Îi voi doborî pe adversarii lui înaintea lui,"],[24,"Dar credincioșia mea și bunătatea mea iubitoare vor fi cu el."],[25,"Îi voi pune mâna și pe mare,"],[26,"El îmi va striga: „Tu ești Tatăl meu,"],[27,"Îl voi numi și primul meu născut,"],[28,"Îmi voi păstra bunătatea mea iubitoare pentru el pentru totdeauna."],[29,"De asemenea, voi face să rămînă în veșnicie sămânța lui,"],[30,"Dacă copiii lui părăsesc legea mea,"],[31,"dacă îmi încalcă legile,"],[32,"atunci le voi pedepsi păcatul cu toiagul,"],[33,"Dar nu voi lua complet bunătatea mea iubitoare de la el,"],[34,"Nu-mi voi încălca legământul,"],[35,"Odată ce am jurat pe sfințenia mea,"],[36,"Odrasla lui va dăinui pentru totdeauna,"],[37,"Va fi stabilit pentru totdeauna ca luna,"],[38,"Dar ai respins și disprețuit."],[39,"Te-ai lepădat de legământul robului tău."],[40,"I-ai dărâmat toate gardurile vii."],[41,"Toți cei care trec pe drum îl jefuiesc."],[42,"Ai înălțat mâna dreaptă a potrivnicilor lui."],[43,"Da, îi întorci tăișul sabiei,"],[44,"Ai pus capăt splendorii lui,"],[45,"I-ai scurtat zilele tinereții."],[46,"Cât timp, Doamne?"],[47,"Amintește-ți cât de scurt este timpul meu,"],[48,"Ce om este cel care va trăi și nu va vedea moartea,"],[49,"Doamne, unde sunt bunătățile tale de odinioară,"],[50,"Adu-ți aminte, Doamne, de ocara robilor Tăi,"],[51,"De care s-au batjocorit vrăjmașii tăi, Doamne,"],[52,"Binecuvântat să fie Domnul în veci."]]],[90,[[1,"Doamne, Tu ai fost locuința noastră pentru toate generațiile."],[2,"Înainte să se nască munții,"],[3,"Îl transformi pe om la distrugere, spunând:"],[4,"Pentru o mie de ani în ochii tai sunt la fel ca ieri când a trecut,"],[5,"Le măturezi în timp ce dorm."],[6,"Dimineața încolțește și răsare."],[7,"Căci suntem mistuiți de mânia ta."],[8,"Ne-ai pus înaintea Ta fărădelegile,"],[9,"Căci toate zilele noastre au trecut în mânia Ta."],[10,"Zilele anilor noștri sunt șaptezeci,"],[11,"Cine știe puterea mâniei tale,"],[12,"Așa că învață-ne să ne numărăm zilele,"],[13,"Încetează-te, Iahve!"],[14,"Să ne satisfacă dimineața cu bunătatea ta iubitoare,"],[15,"Bucură-ne câte zile ne-ai chinuit,"],[16,"Lucrarea ta să se arate slujitorilor tăi,"],[17,"Favoarea Domnului Dumnezeului nostru să fie asupra noastră."]]],[91,[[1,"Cel ce locuiește în locul ascuns al Celui Prea Înalt"],[2,"Voi spune despre Domnul: „El este refugiul meu și fortăreața mea;"],[3,"Căci el te va izbăvi din cursa păsărilor,"],[4,"El te va acoperi cu penele lui."],[5,"Nu te vei teme de teroarea nopții,"],[6,"nici de ciumă care umblă în întuneric,"],[7,"O mie pot cădea lângă tine,"],[8,"Vei privi doar cu ochii tăi,"],[9,"Pentru că ai făcut din Domnul refugiul tău,"],[10,"nu ți se va întâmpla niciun rău,"],[11,"Căci el îi va pune pe îngerii Săi stăpânirea ta,"],[12,"Ei te vor purta în mâinile lor,"],[13,"Vei călca pe leul și pe cobra."],[14,"„Pentru că și-a pus dragostea asupra mea, de aceea îl voi izbăvi."],[15,"El mă va chema și eu îi voi răspunde."],[16,"Îl voi mulțumi cu viață lungă,"]]],[92,[[1,"Este un lucru bun să-i mulțumim Domnului,"],[2,"să vestesc bunătatea ta iubitoare dimineața,"],[3,"cu lăuta cu zece coarde, cu harpa,"],[4,"Căci Tu, Doamne, m-ai bucurat prin lucrarea Ta."],[5,"Cât de mari sunt lucrările Tale, Doamne!"],[6,"Un om nesimțit nu știe,"],[7,"deși cei răi răsare ca iarba,"],[8,"Dar Tu, Doamne, ești pe sus pentru totdeauna."],[9,"Căci iată, dușmanii tăi, Doamne,"],[10,"Dar tu mi-ai înălțat cornul ca pe cel al bouului sălbatic."],[11,"Ochiul meu i-a văzut și pe dușmanii mei."],[12,"Cei neprihăniți vor înflori ca palmierul."],[13,"Sunt plantați în casa Domnului."],[14,"Ei vor produce în continuare fructe la bătrânețe."],[15,"pentru a arăta că Domnul este drept."]]],[93,[[1,"Domnul domnește!"],[2,"Tronul tău este stabilit de mult timp în urmă."],[3,"S-au ridicat inundațiile, Doamne,"],[4,"Deasupra vocilor multor ape,"],[5,"Statutele tale sunt ferme."]]],[94,[[1,"Doamne, Dumnezeul căruia îi aparține răzbunarea,"],[2,"Ridică-te, judecătorul pământului."],[3,"Doamne, până când vor fi cei răi,"],[4,"Ei revarsă cuvinte arogante."],[5,"Ei zdrobesc poporul Tău, Doamne,"],[6,"Ei ucid văduva și străinul,"],[7,"Ei spun: „Nu va vedea,"],[8,"Luați în considerare, nesimțiți dintre oameni;"],[9,"Cel care a implantat urechea, nu va auzi?"],[10,"Cine disciplinează neamurile, nu va pedepsi?"],[11,"Domnul cunoaște gândurile omului,"],[12,"Ferice de omul pe care îl pedepsești, Doamne,"],[13,"ca să-i dai odihnă din zilele necazului,"],[14,"Căci Domnul nu-și va respinge poporul,"],[15,"Căci judecata se va întoarce la dreptate."],[16,"Cine se va ridica pentru mine împotriva celor răi?"],[17,"Dacă Domnul nu ar fi fost ajutorul meu,"],[18,"Când am spus: „Piciorul meu alunecă!”"],[19,"În multitudinea gândurilor mele din mine,"],[20,"Va avea tronul răutății părtășie cu tine,"],[21,"Ei se adună împotriva sufletului celor drepți,"],[22,"Dar Domnul a fost turnul meu înalt,"],[23,"El a adus asupra lor propria lor nelegiuire,"]]],[95,[[1,"O, haideți, să-i cântăm Domnului."],[2,"Să venim înaintea prezenței lui cu mulțumire."],[3,"Căci Domnul este un Dumnezeu mare,"],[4,"În mâna lui sunt locurile adânci ale pământului."],[5,"Marea este a lui și el a făcut-o."],[6,"O, haideți, să ne închinăm și să ne închinăm."],[7,"căci el este Dumnezeul nostru."],[8,"Nu-ți împietri inima, ca la Meriba,"],[9,"când părinţii tăi m-au ispitit,"],[10,"Patruzeci de ani lungi am fost întristat de acea generație,"],[11,"De aceea am jurat în mânia mea,"]]],[96,[[1,"Cântați lui Iahve un cântec nou!"],[2,"Cântați lui Iahve!"],[3,"Vestiți slava Lui între neamuri,"],[4,"Căci Domnul este mare și mult de lăudat!"],[5,"Căci toți zeii popoarelor sunt idoli,"],[6,"Onoarea și măreția sunt în fața lui."],[7,"Dați Domnului, familii de neamuri,"],[8,"Dați Domnului slava cuvenită Numelui Său."],[9,"Închinați-vă Domnului în haine sfinte."],[10,"Spune printre neamuri: „Domnul domnește”."],[11,"Să se veselească cerurile și să se bucure pământul."],[12,"Lasă câmpul și tot ce este în el să se bucure!"],[13,"înaintea Domnului; căci el vine,"]]],[97,[[1,"Domnul domnește!"],[2,"Norii și întunericul sunt în jurul lui."],[3,"Un foc merge înaintea lui,"],[4,"Fulgerul lui luminează lumea."],[5,"Munții se topesc ca ceara în fața Domnului,"],[6,"Cerurile declară dreptatea Lui."],[7,"Să fie de rușine toți cei ce slujesc imaginilor gravate,"],[8,"Sionul a auzit și s-a bucurat."],[9,"Căci Tu, Doamne, ești cel mai sus peste tot pământul."],[10,"Voi care îl iubiți pe Domnul, urâți răul!"],[11,"Lumină este semănată pentru cei drepți,"],[12,"Bucurați-vă în Domnul, oameni neprihăniți!"]]],[98,[[1,"Cântați Domnului un cântec nou,"],[2,"Domnul și-a făcut cunoscută mântuirea."],[3,"El și-a amintit de bunătatea sa iubitoare și de credincioșia lui față de casa lui Israel."],[4,"Faceți zgomot de bucurie Domnului, tot pământul!"],[5,"Cântați laude Domnului cu harpa,"],[6,"Cu trâmbițe și sunet de corn de berbec,"],[7,"Lasă marea să urle cu plinătatea ei;"],[8,"Lasă râurile să bată din palme."],[9,"Să cânte înaintea Domnului,"]]],[99,[[1,"Domnul domnește! Să tremure popoarele."],[2,"Domnul este mare în Sion."],[3,"Lasă-i să laude numele tău măreț și minunat."],[4,"Puterea regelui iubește și dreptatea."],[5,"Înălțați pe Domnul Dumnezeul nostru."],[6,"Moise și Aaron erau printre preoții săi,"],[7,"El le-a vorbit în stâlpul de nor."],[8,"Tu le-ai răspuns: Doamne, Dumnezeul nostru."],[9,"Înălțăți pe Domnul, Dumnezeul nostru."]]],[100,[[1,"Strigați de bucurie Domnului, voi toate țările!"],[2,"Slujiți Domnului cu bucurie."],[3,"Să știți că Domnul, el este Dumnezeu."],[4,"Intră pe porțile lui cu mulțumire,"],[5,"Căci Domnul este bun."]]],[101,[[1,"Voi cânta bunătate iubitoare și dreptate."],[2,"Voi avea grijă să duc o viață fără vină."],[3,"Nu voi pune nimic rău în fața ochilor mei."],[4,"O inimă perversă va fi departe de mine."],[5,"Voi reduce la tăcere pe oricine își calomniază în secret aproapele."],[6,"Ochii mei vor fi ațintiți asupra credincioșilor țării,"],[7,"Cel ce practică înșelăciunea nu va locui în casa mea."],[8,"Dimineață de dimineață, voi nimici pe toți cei răi ai țării,"]]],[102,[[1,"Ascultă-mi rugăciunea, Doamne!"],[2,"Nu-ți ascunde fața de mine în ziua necazului meu."],[3,"Căci zilele mele se consumă ca fumul."],[4,"Inima mea este stricăcioasă ca iarba și uscată,"],[5,"Din cauza vocii gemetei mele,"],[6,"Sunt ca un pelican al pustiei."],[7,"Mă uit și am devenit ca o vrabie care este singură pe acoperiș."],[8,"Dușmanii mei îmi reproșează toată ziua."],[9,"Căci am mâncat cenușa ca pâinea,"],[10,"din pricina mâniei și mâniei tale;"],[11,"Zilele mele sunt ca o umbră lungă."],[12,"Dar Tu, Doamne, vei rămâne pentru totdeauna;"],[13,"Te vei ridica și vei avea milă de Sion,"],[14,"Căci slujitorii tăi se bucură de pietrele ei,"],[15,"Deci națiunile se vor teme de numele Domnului,"],[16,"Căci Domnul a zidit Sionul."],[17,"El a răspuns rugăciunii celor săraci,"],[18,"Aceasta va fi scrisă pentru generația viitoare."],[19,"căci a privit în jos de la înălțimea sanctuarului său."],[20,"pentru a auzi gemetele prizonierului,"],[21,"ca oamenii să vestească Numele Domnului în Sion,"],[22,"când popoarele sunt adunate,"],[23,"Mi-a slăbit puterea de-a lungul cursului."],[24,"Am spus: „Dumnezeule, nu mă lua în mijlocul zilelor mele."],[25,"În vechime, tu ai pus temelia pământului."],[26,"Ei vor pieri, dar tu vei îndura."],[27,"Dar tu ești la fel."],[28,"Copiii slujitorilor tăi vor continua."]]],[103,[[1,"Slavă Domnului, suflete!"],[2,"Slavă Domnului, suflete al meu,"],[3,"care îți iartă toate păcatele,"],[4,"care îți mântuiește viața din distrugere,"],[5,"care-ți satisface dorința cu lucruri bune,"],[6,"Domnul face fapte drepte,"],[7,"El a făcut cunoscut lui Moise căile Lui,"],[8,"Domnul este milostiv și milostiv,"],[9,"El nu va acuza întotdeauna;"],[10,"El nu s-a purtat cu noi după păcatele noastre,"],[11,"Căci precum cerurile sunt sus deasupra pământului,"],[12,"Cât de departe este estul de vest,"],[13,"Precum un tată are milă de copiii săi,"],[14,"Căci el știe cum suntem făcuți."],[15,"Cât despre om, zilele lui sunt ca iarba."],[16,"Căci vântul trece peste el și s-a dus."],[17,"Dar bunătatea iubitoare a Domnului este din veșnicie în veșnicie cu cei ce se tem de El,"],[18,"celor care țin legământul Lui,"],[19,"Domnul și-a așezat tronul în ceruri."],[20,"Lăudați pe Domnul, îngerii Lui,"],[21,"Lăudați pe Domnul, toate oștirile Lui,"],[22,"Lăudați pe Domnul, toate lucrările Lui,"]]],[104,[[1,"Binecuvântează pe Domnul, sufletul meu."],[2,"El se acoperă cu lumină ca cu o haină."],[3,"El pune grinzile camerelor sale în apă."],[4,"El face vânt pe solii săi,"],[5,"El a pus temeliile pământului,"],[6,"L-ai acoperit cu adâncul ca cu o mantie."],[7,"La mustrarea ta au fugit."],[8,"Munții s-au ridicat,"],[9,"Tu ai pus o hotar pe care sa nu treaca,"],[10,"El trimite izvoare în văi."],[11,"Ei dau de băut fiecărui animal de pe câmp."],[12,"Păsările cerului cuibăresc lângă ele."],[13,"El udă munții din camerele sale."],[14,"El face să crească iarba pentru vite,"],[15,"vin care bucură inima omului,"],[16,"Pomii Domnului sunt bine udați,"],[17,"unde păsările își fac cuiburile."],[18,"Munții înalți sunt pentru caprele sălbatice."],[19,"El a desemnat luna pentru anotimpuri."],[20,"Tu faci întunericul și e noapte,"],[21,"Puieții de lei răcnesc după prada lor,"],[22,"Soarele răsare și ei fură,"],[23,"Omul iese la munca lui,"],[24,"Doamne, câte sunt lucrările tale!"],[25,"Acolo este marea mare și lată,"],[26,"Acolo merg corăbiile,"],[27,"Toate astea te asteapta,"],[28,"Le dai; se adună."],[29,"Îți ascunzi fața; sunt tulburi."],[30,"Îți trimiți Spiritul și ei sunt creați."],[31,"Slava Domnului să rămână în veac."],[32,"Se uită la pământ și acesta tremură."],[33,"Voi cânta Domnului cât voi trăi."],[34,"Fie ca meditația mea să fie dulce pentru el."],[35,"Să fie mistuiți păcătoșii de pe pământ."]]],[105,[[1,"Mulțumiți lui Iahve! Spune-i numele!"],[2,"Cântați-i, cântați-i laude!"],[3,"Slavă în numele Său sfânt."],[4,"Căutați pe Domnul și puterea Lui."],[5,"Amintiți-vă de faptele sale minunate pe care le-a făcut:"],[6,"tu, descendența lui Avraam, slujitorul său,"],[7,"El este Domnul, Dumnezeul nostru."],[8,"Și-a adus aminte de legământul Său pentru totdeauna,"],[9,"legământul pe care l-a făcut cu Avraam,"],[10,"și l-a întărit lui Iacov ca o lege;"],[11,"spunând: „Îți voi da țara Canaanului,"],[12,"când erau doar câțiva bărbați la număr,"],[13,"Au mers din neam în neam,"],[14,"Nu a permis nimănui să le facă rău."],[15,"„Nu vă atingeți de unșii mei!"],[16,"A chemat să fie foamete pe pământ."],[17,"El a trimis un om înaintea lor."],[18,"I-au învinețit picioarele cu cătușe."],[19,"până când s-a întâmplat cuvântul lui,"],[20,"Regele a trimis și l-a eliberat,"],[21,"L-a făcut stăpân al casei lui,"],[22,"să-și disciplineze prinții după plăcerea lui,"],[23,"Israel a venit și el în Egipt."],[24,"Și-a sporit foarte mult poporul,"],[25,"El le-a întors inima să-și urască poporul,"],[26,"El l-a trimis pe Moise, slujitorul său,"],[27,"Au făcut minuni printre ei,"],[28,"El a trimis întuneric și a făcut întuneric."],[29,"El le-a transformat apele în sânge,"],[30,"Pământul lor a roiat de broaște,"],[31,"El a vorbit și au venit roiuri de muște,"],[32,"Le-a dat grindină pentru ploaie,"],[33,"El le-a lovit viile și smochinii lor,"],[34,"El a vorbit și au venit lăcustele"],[35,"Au mâncat fiecare plantă din pământul lor,"],[36,"El a lovit și pe toți întâii născuți din țara lor,"],[37,"Le-a scos cu argint și aur."],[38,"Egiptul s-a bucurat când au plecat,"],[39,"A întins un nor ca acoperire,"],[40,"Au întrebat, iar el a adus prepelițe,"],[41,"El a deschis stânca și au țâșnit ape."],[42,"Căci și-a adus aminte de cuvântul Său sfânt,"],[43,"Și-a scos poporul cu bucurie,"],[44,"El le-a dat pământurile popoarelor."],[45,"ca ei să păzească legile Lui,"]]],[106,[[1,"Slavă Domnului!"],[2,"Cine poate rosti faptele puternice ale Domnului,"],[3,"Fericiți cei care țin dreptatea."],[4,"Adu-ți aminte de mine, Doamne, cu favoarea pe care o arăți poporului Tău."],[5,"ca să văd prosperitatea aleșilor tăi,"],[6,"Am păcătuit cu părinţii noştri."],[7,"Părinții noștri nu au înțeles minunile tale în Egipt."],[8,"Cu toate acestea, i-a salvat de dragul numelui său,"],[9,"El a certat și Marea Roșie și s-a secat;"],[10,"El i-a mântuit din mâna celui ce i-a urât,"],[11,"Apele și-au acoperit adversarii."],[12,"Atunci au crezut cuvintele lui."],[13,"Curând au uitat lucrările lui."],[14,"dar a cedat poftei în deșert,"],[15,"El le-a dat cererea lor,"],[16,"L-au invidiat pe Moise și în tabără,"],[17,"Pământul s-a deschis și l-a înghițit pe Datan,"],[18,"Un incendiu a fost aprins în compania lor."],[19,"Au făcut un vițel în Horeb,"],[20,"Astfel și-au schimbat gloria"],[21,"L-au uitat pe Dumnezeu, Mântuitorul lor,"],[22,"lucrări minunate în țara lui Ham,"],[23,"De aceea a spus că îi va nimici,"],[24,"Da, au disprețuit pământul plăcut."],[25,"dar murmurau în corturile lor,"],[26,"De aceea le-a jurat"],[27,"că va răsturna pe urmașii lor printre neamuri,"],[28,"Ei s-au alăturat și lui Baal Peor,"],[29,"Astfel l-au provocat la mânie cu faptele lor."],[30,"Atunci Fineas s-a ridicat și a executat judecata,"],[31,"Acesta i-a fost creditat pentru dreptate,"],[32,"L-au mâniat și pe apele Meriba,"],[33,"pentru că s-au răzvrătit împotriva spiritului lui,"],[34,"Ei nu au distrus popoarele,"],[35,"dar s-au amestecat cu neamurile,"],[36,"Ei și-au slujit idolilor,"],[37,"Da, și-au sacrificat fiii și fiicele lor demonilor."],[38,"Au vărsat sânge nevinovat,"],[39,"Astfel au fost pângăriți cu lucrările lor,"],[40,"De aceea DOMNUL a ars de mânie împotriva poporului Său."],[41,"El i-a dat în mâna neamurilor."],[42,"Dușmanii lor i-au asuprit și ei."],[43,"I-a salvat de multe ori,"],[44,"Cu toate acestea, a privit suferința lor,"],[45,"Și-a adus aminte pentru ei legământul său,"],[46,"I-a făcut să fie și ei de milă"],[47,"Mântuiește-ne, Doamne, Dumnezeul nostru,"],[48,"Binecuvântat să fie Domnul, Dumnezeul lui Israel,"]]],[107,[[1,"Mulțumiți Domnului, că este bun,"],[2,"Să spună cei răscumpărați de Domnul:"],[3,"și s-au adunat din țări,"],[4,"Au rătăcit în pustie într-un mod pustiu."],[5,"Foame si sete,"],[6,"Atunci au strigat către Domnul în necazul lor,"],[7,"El i-a condus și pe un drum drept,"],[8,"Să-l laude pe Domnul pentru bunătatea Lui iubitoare,"],[9,"Căci el satisface sufletul dor."],[10,"Unii stăteau în întuneric și în umbra morții,"],[11,"pentru că s-au răzvrătit împotriva cuvintelor lui Dumnezeu,"],[12,"De aceea le-a doborât inima cu trudă."],[13,"Atunci au strigat către Domnul în necazul lor,"],[14,"El i-a scos din întuneric și din umbra morții,"],[15,"Să-l laude pe Domnul pentru bunătatea Lui iubitoare,"],[16,"Căci a spart porțile de aramă,"],[17,"Proștii sunt chinuiți din cauza neascultării lor,"],[18,"Sufletul lor detestă orice fel de mâncare."],[19,"Atunci ei strigă către Domnul în necazul lor,"],[20,"El își trimite cuvântul și îi vindecă,"],[21,"Să-l laude pe Domnul pentru bunătatea Lui iubitoare,"],[22,"Să aducă jertfe de mulțumire,"],[23,"Cei care coboară la mare cu corăbii,"],[24,"Aceștia văd faptele Domnului,"],[25,"Căci el poruncește și ridică vântul furtunos,"],[26,"Se urcă până la cer; coboară din nou în adâncuri."],[27,"Se clatina înainte și înapoi și se clătinesc ca un om beat,"],[28,"Atunci ei strigă către Domnul în necazul lor,"],[29,"El face furtuna un calm,"],[30,"Atunci se bucură pentru că este calm,"],[31,"Să-l laude pe Domnul pentru bunătatea Lui iubitoare,"],[32,"Să-l înalțe și pe el în adunarea poporului,"],[33,"El transformă râurile într-un deșert,"],[34,"și un pământ roditor într-un pustiu de sare,"],[35,"El transformă un deșert într-un bazin de apă,"],[36,"Acolo îi face pe cei flămânzi să trăiască,"],[37,"semăna câmpuri, plantează vii,"],[38,"El îi binecuvântează și pe ei, astfel încât se înmulțesc foarte mult."],[39,"Din nou, ei sunt diminuați și înclinați"],[40,"El revarsă dispreț asupra prinților,"],[41,"Cu toate acestea, el scoate pe cei nevoiași din suferința lor,"],[42,"Cei drepți o vor vedea și se vor bucura."],[43,"Cine este înțelept va fi atent la aceste lucruri."]]],[108,[[1,"Inima mea este neclintită, Doamne."],[2,"Trezește-te, harpă și liră!"],[3,"Îți voi mulțumi, Doamne, printre neamuri."],[4,"Căci bunătatea ta iubitoare este mare deasupra cerurilor."],[5,"Înălță-te, Doamne, mai presus de ceruri!"],[6,"Pentru ca iubitul tău să fie izbăvit,"],[7,"Dumnezeu a vorbit din sanctuarul Său: „În triumf,"],[8,"Galaad este al meu. Manase este al meu."],[9,"Moab este oala mea de spălat."],[10,"Cine mă va aduce în cetatea întărită?"],[11,"Nu ne-ai respins, Doamne?"],[12,"Dă-ne ajutor împotriva inamicului,"],[13,"Prin Dumnezeu, vom face viteji,"]]],[109,[[1,"Doamne al laudei mele, nu tace,"],[2,"căci au deschis împotriva mea gura celor răi și gura înșelăciunii."],[3,"M-au înconjurat și cu cuvinte de ură,"],[4,"În schimbul dragostei mele, ei sunt adversarii mei;"],[5,"Ei m-au răsplătit rău pentru bine,"],[6,"Pune un om rău peste el."],[7,"Când va fi judecat, să iasă vinovat."],[8,"Să-i fie zilele puține."],[9,"Lăsați copiii săi să fie orfani,"],[10,"Lasă-i copiii să fie cerșetori rătăcitori."],[11,"Lasă creditorul să pună mâna pe tot ce are."],[12,"Să nu fie nimeni care să-i dea bunătate,"],[13,"Să-i fie tăiată posteritatea."],[14,"Să-și aducă aminte de nelegiuirea părinților săi de la Domnul!"],[15,"Să fie înaintea Domnului mereu,"],[16,"pentru că nu și-a amintit să arate bunătate,"],[17,"Da, îi plăcea să blesteme și i-a venit."],[18,"S-a îmbrăcat și cu blestem, ca și cu haina lui."],[19,"Să fie pentru el ca haina cu care se acoperă,"],[20,"Aceasta este răsplata dușmanilor mei de la Domnul,"],[21,"Dar poartă-mă, Doamne, Doamne, pentru numele Tău,"],[22,"căci sunt sărac și nevoiaș."],[23,"dispar ca o umbră de seară."],[24,"Genunchii mei sunt slabi din cauza postului."],[25,"Am devenit și un reproș pentru ei."],[26,"Ajută-mă, Doamne, Dumnezeul meu."],[27,"ca să știe că aceasta este mâna ta;"],[28,"Ei pot blestema, dar tu binecuvântezi."],[29,"Vrăjmașii mei să fie îmbrăcați cu dezonoare."],[30,"Îi voi mulțumi Domnului cu gura mea."],[31,"Căci va sta la dreapta celor nevoiași,"]]],[110,[[1,"Domnul zice Domnului meu: „Șezi la dreapta Mea,"],[2,"Domnul va trimite din Sion toiagul puterii tale."],[3,"Poporul Tău se oferă de bunăvoie în ziua puterii Tale, în aranjament sfânt."],[4,"Domnul a jurat și nu-și va răzgândi:"],[5,"Domnul este la dreapta ta."],[6,"El va judeca printre neamuri."],[7,"El va bea din pârâu pe drum;"]]],[111,[[1,"Slavă Domnului!"],[2,"Lucrările Domnului sunt mari,"],[3,"Opera lui este onoare și măreție."],[4,"El a făcut ca lucrările sale minunate să fie amintite."],[5,"El a dat mâncare celor care se tem de El."],[6,"El a arătat poporului său puterea faptelor sale,"],[7,"Lucrările mâinilor Lui sunt adevărul și dreptatea."],[8,"Ele sunt stabilite pentru totdeauna."],[9,"El a trimis răscumpărarea poporului său."],[10,"Frica de Domnul este începutul înțelepciunii."]]],[112,[[1,"Slavă Domnului!"],[2,"Neamul lui va fi puternic pe pământ."],[3,"Bogăția și bogăția sunt în casa lui."],[4,"Lumina răsare în întuneric pentru cei drepți,"],[5,"Este bine cu omul care se ocupă cu bunăvoință și împrumută."],[6,"Căci nu va fi niciodată zguduit."],[7,"Nu se va teme de veștile rele."],[8,"Inima lui este stabilită."],[9,"S-a împrăștiat, a dat săracilor."],[10,"Cei răi o vor vedea și se vor întrista."]]],[113,[[1,"Slavă Domnului!"],[2,"Binecuvântat să fie numele Domnului,"],[3,"De la răsăritul soarelui până la apusul lui,"],[4,"Domnul este sus peste toate neamurile,"],[5,"Cine este ca Domnul, Dumnezeul nostru,"],[6,"cine se aplecă să vadă în cer și pe pământ?"],[7,"El ridică pe săraci din ţărână,"],[8,"ca să-l aşeze cu prinţi,"],[9,"O așează pe femeia stearpă în casa ei"]]],[114,[[1,"Când Israel a ieșit din Egipt,"],[2,"Iuda a devenit sanctuarul său,"],[3,"Marea a văzut-o și a fugit."],[4,"Munții au sărit ca berbecii,"],[5,"Ce a fost, mare, că ai fugit?"],[6,"Voi, munți, că ați sărit ca berbecii?"],[7,"Tremură, pământule, înaintea Domnului,"],[8,"care a transformat stânca într-un iaz de apă,"]]],[115,[[1,"Nu nouă, Doamne, nu nouă,"],[2,"De ce ar trebui să spună națiunile:"],[3,"Dar Dumnezeul nostru este în ceruri."],[4,"Idolii lor sunt argint și aur,"],[5,"Au guri, dar nu vorbesc."],[6,"Au urechi, dar nu aud."],[7,"Au mâini, dar nu simt."],[8,"Cei care le fac vor fi ca ei;"],[9,"Israele, încrede-te în Domnul!"],[10,"Casa lui Aaron, încrede-te în Domnul!"],[11,"Voi care vă temeți de Domnul, încredeți-vă în Domnul!"],[12,"Iahve isi aduce aminte de noi. El ne va binecuvânta."],[13,"El va binecuvânta pe cei ce se tem de Domnul,"],[14,"Domnul să vă sporească din ce în ce mai mult,"],[15,"Binecuvântat ești de Domnul,"],[16,"Cerurile sunt cerurile Domnului,"],[17,"Morții nu-L laudă pe Domnul,"],[18,"dar noi îl vom binecuvânta pe Domnul,"]]],[116,[[1,"Îl iubesc pe Domnul, pentru că El ascultă glasul meu,"],[2,"Pentru că și-a întors urechea spre mine,"],[3,"Corzile morții m-au înconjurat,"],[4,"Atunci am chemat numele Domnului:"],[5,"Domnul este milostiv și drept."],[6,"Domnul îi păstrează pe cei simpli."],[7,"Întoarce-te la odihna ta, suflete,"],[8,"Căci mi-ai izbăvit sufletul de la moarte,"],[9,"Voi umbla înaintea Domnului în țara celor vii."],[10,"Am crezut, de aceea am spus,"],[11,"am spus în graba mea,"],[12,"Ce îi voi da lui Iehova pentru toate binefacerile Lui pentru mine?"],[13,"Voi lua paharul mântuirii și voi chema numele Domnului."],[14,"Îmi voi împlini jurămintele către Domnul,"],[15,"Prețioasă înaintea Domnului este moartea sfinților Săi."],[16,"Doamne, cu adevărat eu sunt robul Tău."],[17,"Îți voi oferi jertfa de mulțumire,"],[18,"Îmi voi împlini jurămintele către Domnul,"],[19,"în curțile Casei Domnului,"]]],[117,[[1,"Lăudați pe Domnul, toate neamurile!"],[2,"Căci bunătatea Lui iubitoare este mare față de noi."]]],[118,[[1,"Mulțumiți Domnului, că este bun,"],[2,"Să spună Israel acum"],[3,"Să spună acum casa lui Aaron"],[4,"Acum să spună cei ce se tem de Domnul"],[5,"Din necazul meu, am chemat pe Domnul."],[6,"Yahweh este de partea mea. nu o sa-mi fie frica."],[7,"Domnul este de partea mea printre cei care mă ajută."],[8,"Este mai bine să te adăpostești în Domnul,"],[9,"Este mai bine să te adăpostești în Domnul,"],[10,"Toate neamurile m-au înconjurat,"],[11,"M-au înconjurat, da, m-au înconjurat."],[12,"M-au înconjurat ca albinele."],[13,"M-ai împins tare înapoi, ca să mă faci să cad,"],[14,"Yah este puterea și cântecul meu."],[15,"Glasul bucuriei și al mântuirii este în corturile celor drepți."],[16,"Mâna dreaptă a Domnului este înălțată!"],[17,"Nu voi muri, ci voi trăi,"],[18,"Domnul m-a pedepsit aspru,"],[19,"Deschide-mi porțile dreptății."],[20,"Aceasta este poarta Domnului;"],[21,"Îți voi mulțumi, căci mi-ai răspuns,"],[22,"Piatra pe care constructorii au respins-o"],[23,"Aceasta este lucrul lui Yahweh."],[24,"Aceasta este ziua pe care a făcut-o Domnul."],[25,"Salvează-ne acum, te implorăm, Doamne!"],[26,"Binecuvântat este cel ce vine în numele Domnului!"],[27,"Domnul este Dumnezeu și ne-a dat lumină."],[28,"Tu ești Dumnezeul meu și îți voi mulțumi."],[29,"Mulțumiți Domnului, căci este bun,"]]],[119,[[1,"Fericiți cei ale căror căi sunt fără prihană,"],[2,"Fericiți cei care păzesc legile Lui,"],[3,"Da, nu fac nimic rău."],[4,"Ți-ai poruncit poruncile,"],[5,"O, dacă căile mele ar fi neclintite"],[6,"Atunci nu aș fi dezamăgit,"],[7,"Îți voi mulțumi cu inima dreaptă,"],[8,"Voi păzi legile voastre."],[9,"Cum poate un tânăr să-și păstreze calea curată?"],[10,"Din toată inima te-am căutat."],[11,"Am ascuns cuvântul tău în inima mea,"],[12,"Binecuvântat ești, Doamne."],[13,"Cu buzele mele,"],[14,"M-am bucurat de calea mărturiilor tale,"],[15,"Voi medita la poruncile tale,"],[16,"Mă voi desfăta în poruncile Tale."],[17,"Fă bine slujitorului tău."],[18,"Deschide-mi ochii,"],[19,"Sunt un străin pe pământ."],[20,"Sufletul meu este mistuit de dor după rânduielile tale în orice moment."],[21,"I-ai mustrat pe cei mândri, care sunt blestemati,"],[22,"Luați ocara și disprețul de la mine,"],[23,"Deși prinții stau și mă calomniază,"],[24,"Într-adevăr, legile tale sunt plăcerea mea,"],[25,"Sufletul meu este întins în praf."],[26,"Mi-am spus căile, iar tu mi-ai răspuns."],[27,"Lasă-mă să înțeleg învățătura poruncilor tale!"],[28,"Sufletul meu este obosit de întristare;"],[29,"Păzește-mă de calea înșelăciunii."],[30,"Am ales calea adevărului."],[31,"Mă agățăm de legile Tale, Doamne."],[32,"alerg pe calea poruncilor tale,"],[33,"Învață-mă, Doamne, calea poruncilor Tale."],[34,"Dă-mi înțelegere și voi păzi legea Ta."],[35,"Îndrumă-mă pe calea poruncilor Tale,"],[36,"Întoarce-mi inima către legile Tale,"],[37,"Întoarce-mi ochii de la a privi lucruri fără valoare."],[38,"Împlinește-ți promisiunea față de slujitorul tău,"],[39,"Îndepărtează-mi rușinea de care mă tem,"],[40,"Iată, tânjesc după poruncile Tale!"],[41,"Să vină și asupra mea bunătatea Ta iubitoare, Doamne,"],[42,"Așa că voi avea un răspuns pentru cel care mă reproșează,"],[43,"Nu-mi smulge cuvântul adevărului din gură,"],[44,"Așa că voi asculta de legea ta neîncetat,"],[45,"Voi merge în libertate,"],[46,"Voi vorbi și despre legile tale înaintea împăraților,"],[47,"Mă voi desfăta în poruncile Tale,"],[48,"Îmi întind mâinile spre poruncile Tale, pe care le iubesc."],[49,"Adu-ți aminte de cuvântul tău către slujitorul tău,"],[50,"Aceasta este mângâierea mea în suferința mea,"],[51,"Aroganții mă batjocoresc excesiv,"],[52,"Îmi aduc aminte de poruncile Tale din vechime, Doamne,"],[53,"Indignarea a pus stăpânire pe mine,"],[54,"Legile tale au fost cântecele mele"],[55,"Mi-am adus aminte de numele Tău, Doamne, noaptea,"],[56,"Acesta este drumul meu,"],[57,"Domnul este partea mea."],[58,"Ți-am căutat favoarea din toată inima."],[59,"M-am gândit la căile mele,"],[60,"Mă voi grăbi și nu întârzia,"],[61,"Corzile celor răi mă leagă,"],[62,"La miezul nopții mă voi trezi să-ți mulțumesc,"],[63,"Sunt prietenul tuturor celor care se tem de tine,"],[64,"Pământul este plin de bunătatea Ta iubitoare, Doamne."],[65,"Te-ai tratat bine pe robul tău,"],[66,"Învață-mă bună judecată și cunoaștere,"],[67,"Înainte să fiu chinuit, am rătăcit;"],[68,"Ești bun și faci bine."],[69,"Cei mândri mi-au mânjit o minciună."],[70,"Inima lor este la fel de insensibilă ca grăsimea,"],[71,"Este bine pentru mine că am fost chinuit,"],[72,"Legea gurii tale este mai bună pentru mine decât mii de bucăți de aur și argint."],[73,"Mâinile tale m-au făcut și m-au format."],[74,"Cei care se tem de tine mă vor vedea și se vor bucura,"],[75,"Doamne, știu că judecățile Tale sunt drepte,"],[76,"Te rog, lasă bunătatea ta iubitoare să fie pentru mângâierea mea,"],[77,"Să vină asupra mea îndurările tale, ca să trăiesc;"],[78,"Să fie dezamăgiți cei mândri, căci m-au doborât pe nedrept."],[79,"Lasă-i pe cei cărora le este frică de tine să se întoarcă la mine."],[80,"Fie ca inima mea să fie fără prihană față de decretele tale,"],[81,"Sufletul meu leșină pentru mântuirea ta."],[82,"Ochii mei nu înțeleg cuvântul tău."],[83,"Căci am ajuns ca un burduf în fum."],[84,"Câte sunt zilele slujitorului tău?"],[85,"Mândrii mi-au săpat gropi,"],[86,"Toate poruncile tale sunt credincioase."],[87,"Aproape că mă șterseseră de pe pământ,"],[88,"Păstrează-mi viața după bunătatea Ta iubitoare,"],[89,"Doamne, cuvântul Tău este așezat în cer pentru totdeauna."],[90,"Credincioșia ta este pentru toate generațiile."],[91,"Legile tale rămân până astăzi,"],[92,"Dacă legea ta nu ar fi fost plăcerea mea,"],[93,"Nu voi uita niciodată poruncile tale,"],[94,"Sunt a ta."],[95,"Cei răi m-au așteptat, ca să mă nimicească."],[96,"Am văzut o limită a întregii perfecțiuni,"],[97,"Ce iubesc legea ta!"],[98,"Poruncile Tale mă fac mai înțelept decât dușmanii mei,"],[99,"Am mai multă înțelegere decât toți profesorii mei,"],[100,"Înțeleg mai mult decât bătrânii,"],[101,"Mi-am ferit picioarele de orice cale rea,"],[102,"Nu m-am abătut de la rânduielile tale,"],[103,"Cât de dulci sunt promisiunile tale pentru gustul meu,"],[104,"Prin poruncile tale, am pricepere;"],[105,"Cuvântul Tău este o lampă pentru picioarele mele,"],[106,"Am jurat și am confirmat,"],[107,"Sunt foarte chinuit."],[108,"Acceptă, te implor, darurile de bună voie ale gurii mele."],[109,"Sufletul meu este continuu în mâna mea,"],[110,"Cei răi mi-au întins o cursă,"],[111,"Am luat mărturiile tale ca moștenire pentru totdeauna,"],[112,"Mi-am pus inima să împlinesc legile Tale pentru totdeauna,"],[113,"Urăsc bărbații cu mintea dublă,"],[114,"Tu ești ascunzătoarea mea și scutul meu."],[115,"Plecați de la mine, răufăcătorilor,"],[116,"Susține-mă după cuvântul Tău, ca să trăiesc."],[117,"Ține-mă sus și voi fi în siguranță,"],[118,"Tu respingi pe toți cei care se abate de la legile Tale,"],[119,"Ai alungat pe toți cei răi de pe pământ ca pe zgură."],[120,"Carnea îmi tremură de frica de tine."],[121,"Am făcut ceea ce este drept și drept."],[122,"Asigurați-vă bunăstarea servitorului dvs."],[123,"Ochii mei nu caută mântuirea ta,"],[124,"Tratează-te cu slujitorul tău după bunătatea ta iubitoare."],[125,"Eu sunt slujitorul tău. Dă-mi înțelegere,"],[126,"Este timpul să acționezi, Doamne,"],[127,"De aceea iubesc poruncile tale mai mult decât aurul,"],[128,"De aceea consider că toate poruncile tale sunt drepte."],[129,"Mărturiile tale sunt minunate,"],[130,"Intrarea cuvintelor tale dă lumină."],[131,"Am deschis gura larg și am gâfâit,"],[132,"Întoarce-te la mine și ai milă de mine,"],[133,"Stabilește-mi pașii în cuvântul tău."],[134,"Izbăvește-mă de asuprirea omului,"],[135,"Fă-ți fața să strălucească pe slujitorul tău."],[136,"Fluxuri de lacrimi curg pe ochi,"],[137,"Tu ești drept, Doamne."],[138,"Ți-ai poruncit legile tale în dreptate."],[139,"zelul meu mă obosește,"],[140,"Promisiunile tale au fost testate temeinic,"],[141,"Sunt mic și disprețuit."],[142,"Neprihănirea ta este o neprihănire veșnică."],[143,"Necazurile și suferința m-au pus stăpânire pe mine."],[144,"Mărturiile tale sunt drepte pentru totdeauna."],[145,"Am sunat din toată inima."],[146,"Te-am sunat. Salvează-mă!"],[147,"Mă trezesc înainte de zori și strig după ajutor."],[148,"Ochii mei rămân deschiși în timpul ceasurilor de noapte,"],[149,"Ascultă-mi glasul după bunătatea Ta iubitoare."],[150,"Se apropie cei care urmăresc răutatea."],[151,"Ești aproape, Doamne."],[152,"Din vechime am cunoscut din mărturiile tale,"],[153,"Privește necazul meu și izbăvește-mă,"],[154,"Pledează-mi cauza și mântuiește-mă!"],[155,"Mântuirea este departe de cei răi,"],[156,"Mari sunt îndurările Tale, Doamne."],[157,"Mulți sunt persecutorii și adversarii mei."],[158,"Mă uit la cei necredincioși cu dezgust,"],[159,"Gândește-te la cât de mult iubesc poruncile tale."],[160,"Toate cuvintele tale sunt adevăr."],[161,"Prinții m-au persecutat fără motiv,"],[162,"Mă bucur de cuvântul tău,"],[163,"Urăsc și urăsc minciuna."],[164,"De șapte ori pe zi, te laud,"],[165,"Cei care iubesc legea ta au mare pace."],[166,"Am nădăjduit în mântuirea Ta, Doamne."],[167,"Sufletul meu a păzit mărturiile tale."],[168,"Am ascultat de poruncile și mărturiile tale,"],[169,"Să vină strigătul meu înaintea Ta, Doamne."],[170,"Rugăciunea mea să vină înaintea ta."],[171,"Lasă-mi buzele laude,"],[172,"Lasă limba mea să cânte cuvântul tău,"],[173,"Lasă-ți mâna gata să mă ajute,"],[174,"Am tânjit după mântuirea Ta, Doamne."],[175,"Să trăiască sufletul meu, ca să te laud."],[176,"Am rătăcit ca o oaie pierdută."]]],[120,[[1,"În necazul meu, am strigat către Domnul."],[2,"Izbăvește-mi, Doamne, sufletul meu de buzele mincinoase,"],[3,"Ce ți se va da și ce ți se va face mai mult,"],[4,"Săgețile ascuțite ale celor puternici,"],[5,"Vai de mine că locuiesc în Meşec,"],[6,"Sufletul meu a locuit prea mult timp"],[7,"Sunt pentru pace,"]]],[121,[[1,"Îmi voi ridica ochii spre dealuri."],[2,"Ajutorul meu vine de la Domnul,"],[3,"El nu va permite ca piciorul tău să fie mișcat."],[4,"Iată, cel ce păzește pe Israel"],[5,"Domnul este păzitorul tău."],[6,"Soarele nu-ți va face rău ziua,"],[7,"Domnul te va păzi de tot răul."],[8,"Domnul vă va păstra ieșirea și intrarea voastră,"]]],[122,[[1,"M-am bucurat când mi-au spus:"],[2,"Picioarele noastre stau la porțile tale, Ierusalime!"],[3,"Ierusalimul este construit ca o cetate compactă,"],[4,"unde se urcă triburile, chiar triburile lui Yah,"],[5,"Căci sunt tronuri așezate pentru judecată,"],[6,"Roagă-te pentru pacea Ierusalimului."],[7,"Pacea să fie între zidurile voastre,"],[8,"De dragul fraților și tovarășilor mei,"],[9,"De dragul Casei Domnului Dumnezeului nostru,"]]],[123,[[1,"Îmi ridic ochii spre tine,"],[2,"Iată, precum ochii slujitorilor se uită la mâna stăpânului lor,"],[3,"Miluiește-ne pe noi, Doamne, miluiește-ne pe noi,"],[4,"Sufletul nostru este extrem de plin de batjocura celor care sunt în largul lor,"]]],[124,[[1,"Dacă n-ar fi fost Iehova de partea noastră,"],[2,"dacă n-ar fi fost Domnul cel care era de partea noastră,"],[3,"atunci ne-ar fi înghițit de vii,"],[4,"atunci apele ne-ar fi copleșit,"],[5,"Atunci apele mândre ar fi trecut peste sufletul nostru."],[6,"Binecuvântat să fie Domnul,"],[7,"Sufletul nostru a scăpat ca o pasăre din capcana păsărilor."],[8,"Ajutorul nostru este în numele Domnului,"]]],[125,[[1,"Cei care se încred în Domnul sunt ca muntele Sionului,"],[2,"Cum munții înconjoară Ierusalimul,"],[3,"Căci sceptrul răutăţii nu va rămâne peste repartizarea celor drepţi,"],[4,"Fă bine, Doamne, celor ce sunt buni,"],[5,"Dar în ceea ce privește cei care se întorc la căile lor strâmbe,"]]],[126,[[1,"Când Domnul i-a adus înapoi pe cei ce s-au întors în Sion,"],[2,"Atunci ni s-a umplut gura de râs,"],[3,"Domnul a făcut lucruri mari pentru noi,"],[4,"Întoarce-ne averea din nou, Doamne,"],[5,"Cei care seamănă cu lacrimi vor culege cu bucurie."],[6,"Cel ce iese plângând, purtând sămânță pentru semănat,"]]],[127,[[1,"Dacă Domnul nu zidește casa,"],[2,"Este zadarnic să te trezești devreme,"],[3,"Iată, copiii sunt o moștenire a Domnului."],[4,"Ca săgețile în mâna unui puternic,"],[5,"Fericit este omul care are tolba plină de ele."]]],[128,[[1,"Ferice de oricine se teme de Domnul,"],[2,"Căci vei mânca munca mâinilor tale."],[3,"Soția ta va fi ca o viță de vie roditoare în cele mai launuri ale casei tale,"],[4,"Iată, așa este binecuvântat omul care se teme de Domnul."],[5,"Domnul să vă binecuvânteze din Sion,"],[6,"Da, poți să-i vezi pe copiii copiilor tăi."]]],[129,[[1,"De multe ori m-au chinuit din tinerețe în sus."],[2,"de multe ori m-au chinuit din tinerețe în sus,"],[3,"Plugatorii mi-au arat pe spate."],[4,"Domnul este drept."],[5,"Să fie dezamăgiți și întoarse înapoi,"],[6,"Să fie ca iarba de pe acoperișuri,"],[7,"cu care secerătorul nu-și umple mâna,"],[8,"Nici cei care trec nu spun:"]]],[130,[[1,"Din adâncuri am strigat către Tine, Doamne."],[2,"Doamne, ascultă-mi vocea."],[3,"Dacă tu, Doamne, ai ținut o evidență a păcatelor,"],[4,"Dar există iertare cu tine,"],[5,"Îl aștept pe Iahve."],[6,"Sufletul meu tânjește după Domnul mai mult decât străjerii tânjesc după dimineață,"],[7,"Israele, nădăjduiește în Domnul,"],[8,"El va izbăvi pe Israel de toate păcatele lui."]]],[131,[[1,"Doamne, inima mea nu este arogantă, nici ochii mei nu sunt înălțați;"],[2,"Cu siguranță mi-am liniștit și mi-am liniștit sufletul,"],[3,"Israele, nădăjduiește în Domnul,"]]],[132,[[1,"Doamne, adu-ți aminte de David și de toate necazurile lui,"],[2,"cum a jurat pe Domnul,"],[3,"„Cu siguranță nu voi intra în structura casei mele,"],[4,"Nu voi da somn la ochii mei,"],[5,"până voi afla un loc pentru Domnul,"],[6,"Iată, am auzit despre asta în Efrata."],[7,"„Vom merge în locuința lui."],[8,"Ridică-te, Doamne, în locul tău de odihnă,"],[9,"Preoții voștri să fie îmbrăcați cu dreptate."],[10,"De dragul robului tău David,"],[11,"Domnul a jurat lui David în adevăr."],[12,"Dacă copiii tăi vor păzi legământul Meu,"],[13,"Căci Domnul a ales Sionul."],[14,"„Acesta este locul meu de odihnă pentru totdeauna."],[15,"Voi binecuvânta din belșug provizia ei."],[16,"Îi voi îmbrăca și pe preoții ei cu mântuire."],[17,"Voi face să înmugurească acolo cornul lui David."],[18,"Îi voi îmbrăca cu rușine pe vrăjmașii lui,"]]],[133,[[1,"Vezi cât de bun și cât de plăcut este"],[2,"Este ca uleiul prețios de pe cap,"],[3,"ca roua Hermonului,"]]],[134,[[1,"Uite! Lăudați pe Domnul, voi toți slujitorii Domnului,"],[2,"Ridicați-vă mâinile în sanctuar."],[3,"Domnul să vă binecuvânteze din Sion,"]]],[135,[[1,"Slavă Domnului!"],[2,"voi care stați în casa Domnului,"],[3,"Lăudați pe Domnul, căci Domnul este bun."],[4,"Căci Domnul l-a ales pe Iacov pentru Sine,"],[5,"Căci știu că Domnul este mare,"],[6,"Orice a voit Domnul, că a făcut,"],[7,"El face să se ridice norii de la marginile pământului."],[8,"El a lovit pe întâiul născut al Egiptului,"],[9,"El a trimis semne și minuni în mijlocul tău, Egipte,"],[10,"El a lovit multe națiuni,"],[11,"Sihon, regele amoriților,"],[12,"și și-au dat pământul ca moștenire,"],[13,"Numele Tău, Doamne, rămâne în veac;"],[14,"Căci Domnul va judeca poporul Său"],[15,"Idolii neamurilor sunt argint și aur,"],[16,"Au guri, dar nu pot vorbi."],[17,"Au urechi, dar nu aud,"],[18,"Cei care le fac vor fi ca ei,"],[19,"Casa lui Israel, lăudați pe Domnul!"],[20,"Casa lui Levi, lăudați pe Domnul!"],[21,"Binecuvântat să fie Domnul din Sion,"]]],[136,[[1,"Mulțumiți Domnului, că este bun,"],[2,"Mulțumiți Dumnezeului zeilor,"],[3,"Mulțumiți Domnului domnilor,"],[4,"celui care singur face minuni mari,"],[5,"celui care prin pricepere a făcut cerurile,"],[6,"celui care a întins pământul deasupra apelor,"],[7,"celui care a făcut luminile mari,"],[8,"soarele să conducă ziua,"],[9,"luna și stelele să conducă noaptea,"],[10,"celui care a lovit întâiul născut egiptean,"],[11,"și a scos pe Israel din mijlocul lor,"],[12,"cu o mână puternică și cu brațul întins,"],[13,"celui care a împărțit Marea Roșie,"],[14,"și a făcut pe Israel să treacă prin mijlocul ei,"],[15,"dar l-a răsturnat pe Faraon și armata lui în Marea Roșie,"],[16,"celui care a condus poporul său prin pustie,"],[17,"celui care a lovit marii regi,"],[18,"și a ucis regi puternici,"],[19,"Sihon, regele amoriților,"],[20,"Og, regele Basanului,"],[21,"și au dat pământul lor ca moștenire,"],[22,"chiar o moștenire pentru Israel, slujitorul său,"],[23,"care și-a adus aminte de noi în moșia noastră joasă,"],[24,"și ne-a izbăvit de potrivnicii noștri,"],[25,"care dă hrană oricărei făpturi,"],[26,"O, mulțumiți Dumnezeului cerului,"]]],[137,[[1,"Lângă râurile Babilonului, acolo ne-am așezat."],[2,"Pe sălcii din acel pământ,"],[3,"Căci acolo cei care ne-au dus captivi ne-au cerut cântece."],[4,"Cum putem să cântăm cântarea Domnului într-o țară străină?"],[5,"Dacă te uit, Ierusalim,"],[6,"Lasă-mi limba să se lipească de cerul gurii dacă nu-mi amintesc de tine,"],[7,"Adu-ți aminte, Doamne, de copiii lui Edom în ziua Ierusalimului,"],[8,"Fiica Babilonului, sortită pieirii,"],[9,"Fericit va fi,"]]],[138,[[1,"Îți voi mulțumi din toată inima."],[2,"Mă voi închina către templul tău sfânt,"],[3,"În ziua în care am sunat, mi-ai răspuns."],[4,"Toți împărații pământului Îți vor mulțumi, Doamne,"],[5,"Da, vor cânta căile Domnului,"],[6,"Căci, deși Domnul este înalt, totuși El are grijă de cei smeriți;"],[7,"Deși merg în mijlocul necazului, mă vei învia."],[8,"Domnul va împlini ceea ce mă priveşte."]]],[139,[[1,"Doamne, tu m-ai cercetat,"],[2,"Știi că mă așez și mă ridic."],[3,"Căutați calea mea și culcarea mea,"],[4,"Căci nu este un cuvânt pe limba mea,"],[5,"Mă înveți în spate și înainte."],[6,"Această cunoaștere mă depășește."],[7,"Unde aș putea să mă duc de la Spiritul tău?"],[8,"Dacă mă înalț la cer, tu ești acolo."],[9,"Dacă iau aripile zorilor,"],[10,"chiar și acolo mâna ta mă va conduce,"],[11,"Dacă spun: „Cu siguranță întunericul mă va copleși."],[12,"nici măcar întunericul nu se ascunde de tine,"],[13,"Căci tu mi-ai format ființa cea mai interioară."],[14,"Îți voi mulțumi,"],[15,"Cadrul meu nu a fost ascuns de tine,"],[16,"Ochii tăi mi-au văzut corpul."],[17,"Cât de prețioase sunt pentru mine gândurile tale, Doamne!"],[18,"Dacă le-aș număra, sunt mai multe la număr decât nisipul."],[19,"Dacă tu, Doamne, i-ai ucide pe cei răi."],[20,"Căci ei vorbesc împotriva ta cu răutate."],[21,"Doamne, nu-i urăsc pe cei care Te urăsc?"],[22,"Îi urăsc cu o ură perfectă."],[23,"Cercetează-mă, Doamne, și cunoaște-mi inima."],[24,"Vezi dacă există vreo cale rea în mine,"]]],[140,[[1,"Izbăvește-mă, Doamne, de oamenii răi."],[2,"cei care pun la cale răul în inimile lor."],[3,"Și-au ascuțit limba ca șarpele."],[4,"Doamne, păzește-mă de mâinile celor răi."],[5,"Mândrii mi-au ascuns o cursă,"],[6,"I-am spus Domnului: „Tu ești Dumnezeul meu”."],[7,"Domnul, Domnul, puterea mântuirii mele,"],[8,"Doamne, nu împlini dorințele celor răi."],[9,"Cât despre capul celor care mă înconjoară,"],[10,"Lasă cărbunii aprinși să cadă peste ei."],[11,"Un vorbitor rău nu va fi stabilit pe pământ."],[12,"Știu că Domnul va menține cauza celor necăjiți,"],[13,"Cu siguranță cei drepți vor mulțumi numelui tău."]]],[141,[[1,"Doamne, te-am chemat."],[2,"Rugăciunea mea să fie pusă înaintea ta ca tămâia;"],[3,"Pune un ceas, Doamne, înaintea gurii mele."],[4,"Nu-mi înclina inima către niciun lucru rău,"],[5,"Să mă lovească cel drept, este bunătate;"],[6,"Judecătorii lor sunt aruncați de marginile stâncii."],[7,"„Ca când cineva ară și sfărâmă pământul,"],[8,"Căci ochii mei sunt pe Tine, Doamne, Doamne."],[9,"Păzește-mă de cursa pe care mi-au întins-o,"],[10,"Lăsați cei răi să cadă împreună în propriile lor plase"]]],[142,[[1,"strig cu glasul meu către Domnul."],[2,"Îmi revars plângerea în fața lui."],[3,"Când spiritul meu a fost copleșit în mine,"],[4,"Privește în dreapta mea și vezi;"],[5,"Am strigat către Tine, Doamne."],[6,"Ascultă-mi strigătul,"],[7,"Scoate-mi sufletul din închisoare,"]]],[143,[[1,"Ascultă-mi rugăciunea, Doamne."],[2,"Nu intra la judecată cu robul tău,"],[3,"Căci dușmanul îmi urmărește sufletul."],[4,"Prin urmare, spiritul meu este copleșit în mine."],[5,"Îmi amintesc de vremurile de odinioară."],[6,"Mi-am întins mâinile către tine."],[7,"Grăbește-te să-mi răspunzi, Doamne."],[8,"Fă-mă să aud bunătatea ta iubitoare dimineața,"],[9,"Izbăvește-mă, Doamne, de vrăjmașii mei."],[10,"Învață-mă să-ți fac voia,"],[11,"Înviază-mă, Doamne, pentru numele tău."],[12,"În bunătatea ta iubitoare, tăiați-i pe dușmanii mei,"]]],[144,[[1,"Binecuvântat să fie Domnul, stânca mea,"],[2,"bunătatea mea iubitoare, fortăreața mea,"],[3,"Doamne, ce este omul, ca să-ți pasă de el?"],[4,"Omul este ca o respirație."],[5,"Împărți-ți cerurile, Doamne, și coboară."],[6,"Aruncă fulgere și împrăștie-le."],[7,"Întinde-ți mâna de sus,"],[8,"ale căror guri vorbesc înșelăciune,"],[9,"Îți voi cânta un cântec nou, Doamne."],[10,"Tu ești cel care dă mântuirea împăraților,"],[11,"Salvează-mă și izbăvește-mă din mâinile străinilor,"],[12,"Atunci fiii noștri vor fi ca niște plante bine hrănite,"],[13,"Hambarele noastre sunt pline, pline cu tot felul de provizii."],[14,"Boii noștri vor trage încărcături grele."],[15,"Fericiți sunt oamenii care se află într-o astfel de situație."]]],[145,[[1,"Te voi înălța, Dumnezeul meu, Regele."],[2,"În fiecare zi te voi lăuda."],[3,"Mare este Domnul și mult de lăudat!"],[4,"O generație va încredința lucrările tale alteia,"],[5,"Voi medita la măreția glorioasă a onoarei tale,"],[6,"Bărbații vor vorbi despre puterea actelor tale minunate."],[7,"Ei vor rosti amintirea marii tale bunătăți,"],[8,"Domnul este milostiv, milostiv,"],[9,"Domnul este bun cu toți."],[10,"Toate lucrările tale îţi vor mulţumi, Doamne."],[11,"Vor vorbi despre slava împărăției tale,"],[12,"pentru a face cunoscute fiilor oamenilor faptele lui mărețe,"],[13,"Împărăția ta este o împărăție veșnică."],[14,"Domnul sprijină pe toți cei ce cad,"],[15,"Ochii tuturor vă așteaptă."],[16,"Deschizi mana,"],[17,"Domnul este drept în toate căile Lui,"],[18,"Domnul este aproape de toți cei care îl cheamă,"],[19,"El va împlini dorința celor care se tem de El."],[20,"Domnul îi păzește pe toți cei care îl iubesc,"],[21,"Gura mea va rosti lauda Domnului."]]],[146,[[1,"Slavă Domnului!"],[2,"Cât voi trăi, voi lăuda pe Domnul."],[3,"Nu vă puneți încrederea în prinți,"],[4,"Duhul lui pleacă și se întoarce pe pământ."],[5,"Ferice de cel care are ca ajutor pe Dumnezeul lui Iacov,"],[6,"care a făcut cerul și pământul,"],[7,"care face dreptate pentru cei asupriți;"],[8,"Domnul deschide ochii orbilor."],[9,"Domnul îi păzește pe străini."],[10,"Domnul va domni în veac;"]]],[147,[[1,"Slavă Domnului,"],[2,"Domnul zidește Ierusalimul."],[3,"El vindecă pe cei cu inima zdrobită,"],[4,"El numără numărul stelelor."],[5,"Mare este Domnul nostru și puternic în putere."],[6,"Domnul îi susține pe cei smeriți."],[7,"Cântați Domnului cu mulțumire."],[8,"care acoperă cerul cu nori,"],[9,"El oferă hrană pentru animale,"],[10,"Nu se bucură de puterea calului."],[11,"Domnul se bucură de cei ce se tem de El,"],[12,"Slavă Domnului, Ierusalime!"],[13,"Căci El a întărit zăvoarele porților tale."],[14,"El face pace în hotarele tale."],[15,"El își trimite porunca pe pământ."],[16,"El dă zăpada ca lâna,"],[17,"Își aruncă grindina ca niște pietricele."],[18,"El își trimite cuvântul și îi topește."],[19,"El își arată cuvântul lui Iacov,"],[20,"El nu a făcut asta pentru orice națiune."]]],[148,[[1,"Slavă Domnului!"],[2,"Lăudați-l, toți îngerii lui!"],[3,"Lăudați-l, soare și lună!"],[4,"Lăudați-L, ceruri ale cerurilor,"],[5,"Să laude numele Domnului,"],[6,"El le-a întemeiat, de asemenea, pentru totdeauna."],[7,"Lăudați pe Domnul de pe pământ,"],[8,"fulgere și grindină, zăpadă și nori,"],[9,"munții și toate dealurile,"],[10,"animale sălbatice și toate animalele,"],[11,"regii pământului și toate popoarele,"],[12,"atât tinerii cât și fecioarele,"],[13,"Să laude numele Domnului,"],[14,"El a ridicat cornul poporului său,"]]],[149,[[1,"Slavă Domnului!"],[2,"Israel să se bucure de Cel ce i-a făcut."],[3,"Să-i laude numele în dans!"],[4,"Căci Domnul se bucură de poporul Său."],[5,"Să se bucure sfinții de cinste."],[6,"Fie ca înaltele laude ale lui Dumnezeu să fie în gura lor,"],[7,"să se răzbune pe națiuni,"],[8,"să-și lege regii cu lanțuri,"],[9,"sa execute asupra lor judecata scrisa."]]],[150,[[1,"Slavă Domnului!"],[2,"Lăudați-l pentru faptele sale mărețe!"],[3,"Lăudați-l cu sunetul trâmbiței!"],[4,"Lăudați-l cu tamburin și dans!"],[5,"Lăudați-l cu chimvale puternice!"],[6,"Tot ce are suflare să-L laude pe Domnul!"]]]];